/**
 * .agents/scripts/__tests__/nav-registry-diff.test.js — unit + CLI contract for
 * the deterministic route ↔ nav-registry cross-check (Story #4630, AC-4/AC-5).
 *
 * The script is the mechanical half of the navigability lens: it turns the
 * route-tree ↔ nav-registry set-difference into a runnable diff and applies the
 * orphan-verification exemption taxonomy (dynamic children, system routes,
 * inbound references) so the lens reports only genuine orphans.
 */

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';
import { makeTempDir } from '../lib/test-temp.js';
import {
  computeNavDiff,
  formatDiffText,
  isDynamicPath,
  isDynamicSegment,
  isSystemRoute,
  normalizePath,
  parentPath,
  routeTemplateMatchesHref,
} from '../nav-registry-diff.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SCRIPT = path.resolve(HERE, '..', 'nav-registry-diff.js');

describe('normalizePath', () => {
  it('forces a single leading slash and drops a trailing slash', () => {
    assert.equal(normalizePath('users/'), '/users');
    assert.equal(normalizePath('/users'), '/users');
    assert.equal(normalizePath('users/list/'), '/users/list');
  });

  it('collapses duplicate slashes and preserves root', () => {
    assert.equal(normalizePath('//users//list'), '/users/list');
    assert.equal(normalizePath('/'), '/');
  });

  it('returns empty string for nullish or blank input', () => {
    assert.equal(normalizePath(''), '');
    assert.equal(normalizePath('   '), '');
    assert.equal(normalizePath(null), '');
    assert.equal(normalizePath(undefined), '');
    assert.equal(normalizePath(42), '');
  });
});

describe('dynamic + system segment classification', () => {
  it('recognizes dynamic segment syntaxes', () => {
    assert.equal(isDynamicSegment(':id'), true);
    assert.equal(isDynamicSegment('[id]'), true);
    assert.equal(isDynamicSegment('[...slug]'), true);
    assert.equal(isDynamicSegment('{id}'), true);
    assert.equal(isDynamicSegment('*'), true);
    assert.equal(isDynamicSegment('users'), false);
  });

  it('flags a path with any dynamic segment', () => {
    assert.equal(isDynamicPath('/users/:id'), true);
    assert.equal(isDynamicPath('/blog/[slug]/edit'), true);
    assert.equal(isDynamicPath('/users/list'), false);
  });

  it('flags system routes by their last segment', () => {
    assert.equal(isSystemRoute('/login'), true);
    assert.equal(isSystemRoute('/auth/callback'), true);
    assert.equal(isSystemRoute('/404'), true);
    assert.equal(isSystemRoute('/unauthorized'), true);
    assert.equal(isSystemRoute('/dashboard'), false);
    assert.equal(isSystemRoute('/'), false);
  });
});

describe('parentPath', () => {
  it('strips the last segment, bottoming out at root', () => {
    assert.equal(parentPath('/users/:id'), '/users');
    assert.equal(parentPath('/users'), '/');
    assert.equal(parentPath('/'), '/');
    assert.equal(parentPath('/a/b/c'), '/a/b');
  });
});

describe('routeTemplateMatchesHref', () => {
  it('matches an identical static path', () => {
    assert.equal(routeTemplateMatchesHref('/users', '/users'), true);
    assert.equal(routeTemplateMatchesHref('/users', '/teams'), false);
  });

  it('matches a dynamic segment against any concrete segment', () => {
    assert.equal(routeTemplateMatchesHref('/users/:id', '/users/42'), true);
    assert.equal(routeTemplateMatchesHref('/blog/[slug]', '/blog/hello'), true);
  });

  it('rejects a length mismatch on a non-catch-all template', () => {
    assert.equal(routeTemplateMatchesHref('/users/:id', '/users'), false);
    assert.equal(
      routeTemplateMatchesHref('/users/:id', '/users/42/edit'),
      false,
    );
  });

  it('lets a catch-all consume one or more trailing segments', () => {
    assert.equal(routeTemplateMatchesHref('/docs/[...path]', '/docs/a'), true);
    assert.equal(
      routeTemplateMatchesHref('/docs/[...path]', '/docs/a/b/c'),
      true,
    );
    assert.equal(routeTemplateMatchesHref('/docs/*', '/docs/a/b'), true);
    // A catch-all still needs at least one trailing segment.
    assert.equal(routeTemplateMatchesHref('/docs/[...path]', '/docs'), false);
  });
});

describe('computeNavDiff — the two invariants', () => {
  it('flags an orphaned route with no nav door', () => {
    const diff = computeNavDiff({
      routes: ['/dashboard', '/reports'],
      nav: ['/dashboard'],
    });
    assert.deepEqual(
      diff.orphanedRoutes.map((o) => o.path),
      ['/reports'],
    );
    assert.deepEqual(diff.deadHrefs, []);
    assert.deepEqual(diff.counts, { routes: 2, doors: 1 });
  });

  it('flags a dead nav href pointing at no route', () => {
    const diff = computeNavDiff({
      routes: ['/dashboard'],
      nav: ['/dashboard', '/ghost'],
    });
    assert.deepEqual(
      diff.deadHrefs.map((d) => d.href),
      ['/ghost'],
    );
    assert.deepEqual(diff.orphanedRoutes, []);
  });

  it('treats a door as surfacing a dynamic route via template match', () => {
    const diff = computeNavDiff({
      routes: ['/users/:id'],
      nav: ['/users/42'],
    });
    // The concrete href resolves to the template, so no dead href …
    assert.deepEqual(diff.deadHrefs, []);
    // … and the route is surfaced, so it is not orphaned.
    assert.deepEqual(diff.orphanedRoutes, []);
  });
});

describe('computeNavDiff — orphan-verification exemption taxonomy (AC-5)', () => {
  it('exempts an explicitly-flagged route', () => {
    const diff = computeNavDiff({
      routes: [{ path: '/internal', exempt: true }],
      nav: [],
    });
    assert.deepEqual(diff.orphanedRoutes, []);
    assert.deepEqual(diff.exemptRoutes, [
      { path: '/internal', reason: 'explicit-exempt' },
    ]);
  });

  it('exempts a system route (login / 404)', () => {
    const diff = computeNavDiff({
      routes: ['/login', '/404'],
      nav: [],
    });
    assert.deepEqual(diff.orphanedRoutes, []);
    assert.deepEqual(diff.exemptRoutes.map((e) => e.reason).sort(), [
      'system-route',
      'system-route',
    ]);
  });

  it('exempts a dynamic-segment child of a surfaced parent', () => {
    const diff = computeNavDiff({
      routes: ['/users', '/users/:id'],
      nav: ['/users'],
    });
    assert.deepEqual(diff.orphanedRoutes, []);
    assert.deepEqual(diff.exemptRoutes, [
      { path: '/users/:id', reason: 'dynamic-child-of-surfaced-parent' },
    ]);
  });

  it('does NOT exempt a dynamic child when the parent is itself unsurfaced', () => {
    const diff = computeNavDiff({
      routes: ['/users', '/users/:id'],
      nav: [],
    });
    // Parent /users is orphaned; the dynamic child is a genuine orphan too.
    assert.deepEqual(diff.orphanedRoutes.map((o) => o.path).sort(), [
      '/users',
      '/users/:id',
    ]);
  });

  it('exempts a route reached only by an in-app inbound reference', () => {
    const diff = computeNavDiff({
      routes: ['/settings/advanced'],
      nav: [],
      refs: ['/settings/advanced'],
    });
    assert.deepEqual(diff.orphanedRoutes, []);
    assert.deepEqual(diff.exemptRoutes, [
      { path: '/settings/advanced', reason: 'inbound-in-app-reference' },
    ]);
  });
});

describe('computeNavDiff — persona entitlement', () => {
  it('requires a persona intersection when both sides declare one', () => {
    const diff = computeNavDiff({
      routes: [{ path: '/admin', personas: ['admin'] }],
      nav: [{ href: '/admin', persona: 'member' }],
    });
    // The door renders in the wrong persona shell → the route stays orphaned.
    assert.deepEqual(
      diff.orphanedRoutes.map((o) => o.path),
      ['/admin'],
    );
    // …but the href still resolves to a real route, so it is not dead.
    assert.deepEqual(diff.deadHrefs, []);
  });

  it('surfaces when the door persona is entitled', () => {
    const diff = computeNavDiff({
      routes: [{ path: '/admin', personas: ['admin', 'owner'] }],
      nav: [{ href: '/admin', persona: 'owner' }],
    });
    assert.deepEqual(diff.orphanedRoutes, []);
  });

  it('surfaces for any persona when the door declares none', () => {
    const diff = computeNavDiff({
      routes: [{ path: '/admin', personas: ['admin'] }],
      nav: [{ href: '/admin' }],
    });
    assert.deepEqual(diff.orphanedRoutes, []);
  });
});

describe('input coercion', () => {
  it('accepts bare-string and object entries interchangeably', () => {
    const diff = computeNavDiff({
      routes: ['/a', { path: '/b' }],
      nav: ['/a', { href: '/b' }],
    });
    assert.deepEqual(diff.orphanedRoutes, []);
    assert.deepEqual(diff.deadHrefs, []);
  });

  it('throws on a route entry with no usable path', () => {
    assert.throws(
      () => computeNavDiff({ routes: [{ personas: ['x'] }], nav: [] }),
      /no usable "path"/,
    );
  });

  it('throws on a nav entry with no usable href', () => {
    assert.throws(
      () => computeNavDiff({ routes: [], nav: [{ persona: 'x' }] }),
      /no usable "href"/,
    );
  });
});

describe('formatDiffText', () => {
  it('renders counts, orphans, dead hrefs, and exemptions', () => {
    const text = formatDiffText(
      computeNavDiff({
        routes: ['/dashboard', '/reports', '/login', '/users/:id', '/users'],
        nav: ['/dashboard', '/users', '/ghost'],
      }),
    );
    assert.match(text, /routes: 5 {3}nav doors: 3/);
    assert.match(text, /orphaned routes: 1/);
    assert.match(text, /- \/reports/);
    assert.match(text, /dead nav hrefs: 1/);
    assert.match(text, /- \/ghost/);
    assert.match(text, /exempt \(verified, not reported\): 2/);
  });
});

// ---------------------------------------------------------------------------
// CLI contract (AC-4): the script runs over a fixture route tree + nav registry,
// prints the two-way diff, and exits 0.
// ---------------------------------------------------------------------------

/** Write JSON fixtures into an isolated temp dir; return their paths. */
function writeFixtures({ routes, nav, refs }) {
  const dir = makeTempDir('nav-registry-diff-');
  const routesFile = path.join(dir, 'routes.json');
  const navFile = path.join(dir, 'nav.json');
  writeFileSync(routesFile, JSON.stringify(routes));
  writeFileSync(navFile, JSON.stringify(nav));
  const out = { routesFile, navFile };
  if (refs) {
    out.refsFile = path.join(dir, 'refs.json');
    writeFileSync(out.refsFile, JSON.stringify(refs));
  }
  return out;
}

describe('CLI', () => {
  it('prints the two-way diff and exits 0 over a fixture (AC-4)', () => {
    const { routesFile, navFile } = writeFixtures({
      routes: ['/dashboard', '/reports', '/login', '/users/:id', '/users'],
      nav: ['/dashboard', '/users', '/ghost'],
    });
    // execFileSync throws on a non-zero exit, so reaching the assertions proves
    // exit 0.
    const stdout = execFileSync('node', [
      SCRIPT,
      '--routes',
      routesFile,
      '--nav',
      navFile,
    ]).toString();
    assert.match(stdout, /Route ↔ nav-registry diff/);
    assert.match(stdout, /orphaned routes: 1/);
    assert.match(stdout, /dead nav hrefs: 1/);
  });

  it('emits machine-readable JSON under --json', () => {
    const { routesFile, navFile } = writeFixtures({
      routes: ['/a', '/b'],
      nav: ['/a'],
    });
    const stdout = execFileSync('node', [
      SCRIPT,
      '--routes',
      routesFile,
      '--nav',
      navFile,
      '--json',
    ]).toString();
    const parsed = JSON.parse(stdout);
    assert.deepEqual(
      parsed.orphanedRoutes.map((o) => o.path),
      ['/b'],
    );
  });

  it('exits non-zero under --strict when genuine findings remain', () => {
    const { routesFile, navFile } = writeFixtures({
      routes: ['/a', '/b'],
      nav: ['/a'],
    });
    assert.throws(
      () =>
        execFileSync('node', [
          SCRIPT,
          '--routes',
          routesFile,
          '--nav',
          navFile,
          '--strict',
        ]),
      /Command failed/,
    );
  });

  it('exits 0 under --strict when the diff is clean', () => {
    const { routesFile, navFile } = writeFixtures({
      routes: ['/a'],
      nav: ['/a'],
    });
    const stdout = execFileSync('node', [
      SCRIPT,
      '--routes',
      routesFile,
      '--nav',
      navFile,
      '--strict',
    ]).toString();
    assert.match(stdout, /orphaned routes: 0/);
  });

  it('honours a --refs exemption file', () => {
    const { routesFile, navFile, refsFile } = writeFixtures({
      routes: ['/hidden'],
      nav: [],
      refs: ['/hidden'],
    });
    const stdout = execFileSync('node', [
      SCRIPT,
      '--routes',
      routesFile,
      '--nav',
      navFile,
      '--refs',
      refsFile,
      '--json',
    ]).toString();
    const parsed = JSON.parse(stdout);
    assert.deepEqual(parsed.orphanedRoutes, []);
    assert.equal(parsed.exemptRoutes[0].reason, 'inbound-in-app-reference');
  });

  it('errors when a required flag is missing', () => {
    const { routesFile } = writeFixtures({ routes: ['/a'], nav: [] });
    assert.throws(
      () => execFileSync('node', [SCRIPT, '--routes', routesFile]),
      /Command failed/,
    );
  });
});

/**
 * CLI: ratchet-down gate on provenance citations in workflow prose.
 *
 * Workflow documents ride resident in an executing agent's context. A
 * `(Story #1234)` aside costs the same tokens as instruction and teaches
 * the model Mandrel's own history instead of the task in front of it. The
 * citations that survive are the ones a reader must follow to act; the
 * rest belong in the commit trail and `docs/decisions.md`.
 *
 * Nothing stops the tax re-accumulating one well-meaning aside at a time,
 * so this gate holds the line: count every issue-shaped reference across
 * `.agents/workflows/**\/*.md` and fail when the total rises above the
 * committed baseline at `baselines/workflow-citations.json`.
 *
 * The counted token is the bare `#NNNN` form rather than the
 * `(Story|Epic|issue|refs) #NNNN` phrasing, because the same citation is
 * written both ways — `(Story #4593)` and a bare `(#4593)` — and a gate
 * that only saw the prefixed form would wave the other one through.
 *
 * Ratchet semantics mirror `check-arch-cycles.js`:
 *   - Total above the baseline → exit 1, with the files that grew.
 *   - Total below the baseline → printed as shrinkage, exit 0. Refresh the
 *     baseline with `--update` to lock the reduction in.
 *   - Equal → exit 0.
 *
 * Flags:
 *   --baseline <path>  override the baseline path (default
 *                      `baselines/workflow-citations.json`, resolved from cwd)
 *   --root <path>      scan a different workflow root (default
 *                      `.agents/workflows`)
 *   --update           rewrite the baseline from the live count
 *   --json             write the structured envelope to stdout
 */

import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { runAsCli } from './lib/cli-utils.js';

/** Default workflow root, relative to the repository root. */
const DEFAULT_ROOT = path.join('.agents', 'workflows');

/** Default baseline path, relative to the repository root. */
const DEFAULT_BASELINE = path.join('baselines', 'workflow-citations.json');

/**
 * Issue-shaped reference: a `#` followed by 3–5 digits. Narrow enough to
 * skip markdown headings and anchor links, wide enough to catch both the
 * `(Story #1234)` and bare `(#1234)` spellings of one citation.
 */
const CITATION_RE = /#\d{3,5}\b/g;

/**
 * Parse argv. Exported so unit tests can pin the parser.
 *
 * @param {string[]} argv
 * @returns {{ baselinePath: string | null, rootPath: string | null, update: boolean, json: boolean }}
 */
export function parseArgv(argv = []) {
  const out = {
    baselinePath: null,
    rootPath: null,
    update: false,
    json: false,
  };
  for (let i = 0; i < argv.length; i += 1) {
    const flag = argv[i];
    const next = argv[i + 1];
    const takesValue = next && !next.startsWith('--');
    if (flag === '--baseline' && takesValue) {
      out.baselinePath = next;
      i += 1;
    } else if (flag === '--root' && takesValue) {
      out.rootPath = next;
      i += 1;
    } else if (flag === '--update') {
      out.update = true;
    } else if (flag === '--json') {
      out.json = true;
    }
  }
  return out;
}

/**
 * Recursively collect `.md` files under `rootDir`. Returns absolute paths,
 * sorted for determinism.
 *
 * @param {string} rootDir
 * @returns {string[]}
 */
export function collectMarkdownFiles(rootDir) {
  const out = [];
  const walk = (dir) => {
    let entries;
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.isFile() && entry.name.endsWith('.md')) out.push(full);
    }
  };
  walk(rootDir);
  return out.sort();
}

/**
 * Pure helper: count citations in source text.
 *
 * @param {string} source
 * @returns {number}
 */
export function countCitations(source) {
  return (String(source ?? '').match(CITATION_RE) ?? []).length;
}

/**
 * Count citations across a file set, relativizing paths against `cwd` so
 * the report serializes identically on every platform. Files with zero
 * citations are omitted — the baseline records where the tax lives.
 *
 * @param {string[]} files absolute paths
 * @param {string} cwd
 * @param {{ readFile?: (p: string) => string }} [opts]
 * @returns {{ total: number, files: Array<{ path: string, count: number }> }}
 */
export function tallyCitations(files, cwd, { readFile } = {}) {
  const read = readFile ?? ((p) => fs.readFileSync(p, 'utf-8'));
  const rows = [];
  let total = 0;
  for (const file of files) {
    let count;
    try {
      count = countCitations(read(file));
    } catch {
      continue;
    }
    if (count === 0) continue;
    total += count;
    rows.push({
      path: path.relative(cwd, file).split(path.sep).join('/'),
      count,
    });
  }
  return { total, files: rows.sort((a, b) => a.path.localeCompare(b.path)) };
}

/**
 * Pure helper: read the baseline envelope. Returns `null` when the file is
 * missing or unparseable — the baseline is not distributed to consumers, so
 * its absence degrades to "no ceiling" rather than a false failure.
 *
 * @param {string} baselinePath
 * @returns {{ total?: number, files?: Array<{ path: string, count: number }> } | null}
 */
export function loadBaseline(baselinePath) {
  try {
    const parsed = JSON.parse(fs.readFileSync(baselinePath, 'utf-8'));
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * Pure helper: diff the live tally against the baseline. `grew` names the
 * files whose per-file count rose, so a failure points at the edit rather
 * than only at the total.
 *
 * @param {{ total?: number, files?: Array<{ path: string, count: number }> } | null} baseline
 * @param {{ total: number, files: Array<{ path: string, count: number }> }} tally
 * @returns {{ baselineTotal: number | null, delta: number | null, grew: Array<{ path: string, from: number, to: number }> }}
 */
export function diffTally(baseline, tally) {
  const baselineTotal =
    typeof baseline?.total === 'number' ? baseline.total : null;
  const prior = new Map(
    (baseline?.files ?? []).map((row) => [row.path, row.count]),
  );
  const grew = tally.files
    .map((row) => ({
      path: row.path,
      from: prior.get(row.path) ?? 0,
      to: row.count,
    }))
    .filter((row) => row.to > row.from);
  return {
    baselineTotal,
    delta: baselineTotal === null ? null : tally.total - baselineTotal,
    grew,
  };
}

/**
 * Pure helper: render the human-readable diff, mirroring the `+` / `-`
 * vocabulary of the sibling ratchets.
 *
 * @param {{ baselineTotal: number | null, delta: number | null, grew: Array<{ path: string, from: number, to: number }> }} diff
 * @param {{ total: number }} tally
 * @returns {string}
 */
export function renderDiff(diff, tally) {
  const lines = [];
  for (const row of diff.grew) {
    lines.push(`+ ${row.path}: ${row.from} -> ${row.to}`);
  }
  if (diff.delta !== null && diff.delta < 0) {
    lines.push(
      `[workflow-citations] ⚠ ${-diff.delta} citation(s) below baseline — refresh with --update to lock the reduction in`,
    );
  }
  const tag = diff.delta !== null && diff.delta > 0 ? '(gate fail)' : '(ok)';
  lines.push(
    `[workflow-citations] total=${tally.total} baseline=${diff.baselineTotal ?? 'none'} ${tag}`,
  );
  return lines.join('\n');
}

/**
 * Top-level CLI entry. Exported so tests can drive the pipeline against a
 * tmpdir fixture corpus.
 *
 * @param {{
 *   argv?: string[],
 *   cwd?: string,
 *   stdout?: { write: (s: string) => void },
 *   stderr?: { write: (s: string) => void },
 * }} [opts]
 * @returns {Promise<number>} 0 = at or below baseline; 1 = regression
 */
export async function runCli({
  argv = process.argv.slice(2),
  cwd = process.cwd(),
  stdout = process.stdout,
  stderr = process.stderr,
} = {}) {
  const { baselinePath, rootPath, update, json } = parseArgv(argv);
  const root = path.resolve(cwd, rootPath ?? DEFAULT_ROOT);
  const resolvedBaselinePath = path.resolve(
    cwd,
    baselinePath ?? DEFAULT_BASELINE,
  );
  if (!fs.existsSync(root)) {
    throw new Error(`[workflow-citations] workflow root not found: ${root}`);
  }

  const tally = tallyCitations(collectMarkdownFiles(root), cwd);

  if (update) {
    const envelope = {
      $schema: 'https://mandrel.dev/baselines/workflow-citations.schema.json',
      generatedAt: new Date().toISOString(),
      total: tally.total,
      files: tally.files,
    };
    fs.mkdirSync(path.dirname(resolvedBaselinePath), { recursive: true });
    fs.writeFileSync(
      resolvedBaselinePath,
      `${JSON.stringify(envelope, null, 2)}\n`,
    );
    stdout.write(
      `[workflow-citations] baseline written: ${resolvedBaselinePath} (total=${tally.total})\n`,
    );
    return 0;
  }

  const baseline = loadBaseline(resolvedBaselinePath);
  const diff = diffTally(baseline, tally);
  const exitCode = diff.delta !== null && diff.delta > 0 ? 1 : 0;

  if (json) {
    stdout.write(
      `${JSON.stringify(
        {
          kind: 'workflow-citations-report',
          root,
          baselinePath: resolvedBaselinePath,
          total: tally.total,
          baselineTotal: diff.baselineTotal,
          delta: diff.delta,
          files: tally.files,
          grew: diff.grew,
          exitCode,
        },
        null,
        2,
      )}\n`,
    );
    return exitCode;
  }

  if (!baseline) {
    stderr.write(
      `[workflow-citations] ⚠ baseline not found at ${resolvedBaselinePath} — no ceiling enforced\n`,
    );
  }
  stdout.write(`\n--- workflow-citations preview ---\n`);
  stdout.write(`${renderDiff(diff, tally)}\n`);
  return exitCode;
}

async function main() {
  return runCli();
}

runAsCli(import.meta.url, main, {
  source: 'workflow-citations',
  propagateExitCode: true,
  errorPrefix: '[workflow-citations] ❌ Fatal error',
  usage: {
    invocation:
      'node .agents/scripts/check-workflow-citations.js [--baseline <path>] [--root <dir>] [--update] [--json]',
    summary:
      'Ratchet on provenance citations in workflow prose: count issue-shaped references across .agents/workflows/** and fail when the total rises above the recorded baseline.',
    flags: [
      [
        '--baseline <path>',
        'Baseline file (default: baselines/workflow-citations.json).',
      ],
      ['--root <dir>', 'Workflow root to scan (default: .agents/workflows).'],
      ['--update', 'Rewrite the baseline from the live count.'],
      ['--json', 'Emit the comparison envelope as JSON.'],
    ],
    notes: [
      'Exit codes:\n  0  at or below the baseline\n  1  the citation total regressed above the baseline',
    ],
  },
});

/**
 * engine.js — assemble the `/audit-baselines` evidence envelope
 * (Story #4902).
 *
 * Strictly read-only and strictly offline: it reads committed baselines, the
 * resolved config, git history, the static import graph, and any friction
 * ledger it finds. It never writes under `baselines/`, never refreshes a
 * baseline, and never runs a test, coverage, or mutation suite — the whole
 * point is that a baseline review costs a file read, not a CI run.
 *
 * Findings are evidence, not a verdict: assembling the envelope is success,
 * however alarming its contents, so the CLI exits 0 whenever it got this far.
 * Judgment belongs to the lens that reads the envelope.
 *
 * @module lib/audit-baselines/engine
 */

import path from 'node:path';
import { mainCheckoutRoot, tempRootFrom } from '../config/temp-paths.js';
import { getQuality, resolveConfig } from '../config-resolver.js';
import { buildGateSurface } from './gate-surface.js';
import { buildHeadroom } from './headroom.js';
import { buildHotspots } from './hotspots.js';
import { ALL_KINDS, baselinePathFor, GATE_KINDS } from './kinds.js';
import { DEFAULT_TOP_N, extractOutliers } from './outliers.js';
import { buildTrend } from './trend.js';
import {
  makeWeightResolver,
  readCentrality,
  readChurn,
  readFriction,
} from './weights.js';

/** Envelope `kind` discriminator; matches the shipped schema's const. */
const ENVELOPE_KIND = 'audit-baselines-envelope';

/** Envelope schema version — bumped on any breaking shape change. */
const ENVELOPE_SCHEMA_VERSION = '1';

/** Cap on emitted hotspot clusters, independent of the per-gate `topN`. */
export const DEFAULT_HOTSPOT_LIMIT = 50;

/**
 * Resolve the repository config without letting a broken `.agentrc.json`
 * abort the run — an unreadable config still leaves the baseline files
 * themselves readable at their default paths.
 *
 * @param {string} cwd
 * @returns {{ quality: object, configError: string | null }}
 */
function resolveQualityBlock(cwd) {
  try {
    return { quality: getQuality(resolveConfig({ cwd })), configError: null };
  } catch (err) {
    return { quality: { gates: {} }, configError: err?.message ?? String(err) };
  }
}

/**
 * Absolute temp root the friction ledger is searched under, anchored to the
 * **analysed** repository rather than the process cwd. `resolvedTempRoot()`
 * anchors to whichever checkout the current process sits in, which is the
 * right answer for a writer and the wrong one here: an engine pointed at
 * another repo with `--cwd` must read that repo's ledger, not this one's.
 *
 * @param {string} cwd
 * @returns {string}
 */
function tempRootFor(cwd) {
  let relative = 'temp';
  try {
    relative = tempRootFrom(resolveConfig({ cwd }));
  } catch {
    // Unreadable config — the framework default root is still worth probing.
  }
  if (path.isAbsolute(relative)) return relative;
  return path.join(mainCheckoutRoot(cwd) ?? cwd, relative);
}

/**
 * Run the engine and return the envelope object. Pure with respect to the
 * filesystem apart from the reads named in the module docstring — writing
 * the result is the caller's job.
 *
 * @param {{
 *   cwd: string,
 *   topN?: number,
 *   hotspotLimit?: number,
 *   trendDepth?: number,
 *   now?: Date,
 * }} args
 * @returns {object} the `audit-baselines-envelope`
 */
export function runEngine({
  cwd,
  topN = DEFAULT_TOP_N,
  hotspotLimit = DEFAULT_HOTSPOT_LIMIT,
  trendDepth = 5,
  now = new Date(),
}) {
  const { quality, configError } = resolveQualityBlock(cwd);
  const { entries, baselines } = buildGateSurface({ cwd, quality, now });

  const outliers = ALL_KINDS.flatMap((kind) =>
    extractOutliers({ kind, baseline: baselines.get(kind) ?? null, topN }),
  );

  const churn = readChurn({ cwd });
  const centrality = readCentrality({ cwd });
  const friction = readFriction({ tempRootAbs: tempRootFor(cwd) });

  return {
    kind: ENVELOPE_KIND,
    schemaVersion: ENVELOPE_SCHEMA_VERSION,
    generatedAt: now.toISOString(),
    cwd,
    topN,
    configError,
    degradations: {
      gitHistory: churn.degraded,
      importGraph: centrality.degraded,
      frictionLedger: friction.degraded,
    },
    gateSurface: entries,
    hotspots: buildHotspots({
      outliers,
      weightsFor: makeWeightResolver({ churn, centrality, friction }),
      limit: hotspotLimit,
    }),
    trend: buildTrend({
      cwd,
      kinds: ALL_KINDS,
      pathFor: (kind) => baselinePathFor(kind, quality),
      depth: trendDepth,
    }),
    headroom: buildHeadroom({ kinds: GATE_KINDS, quality, baselines }),
  };
}

/**
 * Condense an envelope into the pure-JSON stdout summary. Small enough to
 * read in a terminal, and never carrying a row set.
 *
 * @param {object} envelope
 * @param {string} outPath absolute path the full envelope was written to
 * @returns {object}
 */
export function summarize(envelope, outPath) {
  return {
    kind: 'audit-baselines-summary',
    schemaVersion: ENVELOPE_SCHEMA_VERSION,
    out: outPath,
    generatedAt: envelope.generatedAt,
    gateSurface: {
      total: envelope.gateSurface.length,
      configured: envelope.gateSurface.filter((g) => g.configured).length,
      missingBaseline: envelope.gateSurface
        .filter((g) => !g.baselineExists)
        .map((g) => g.kind),
      stubs: envelope.gateSurface.filter((g) => g.stub).map((g) => g.kind),
      deadIgnoreGlobs: envelope.gateSurface.reduce(
        (n, g) => n + g.deadIgnoreGlobs.length,
        0,
      ),
    },
    hotspots: {
      total: envelope.hotspots.length,
      multiGate: envelope.hotspots.filter((h) => h.gateCount > 1).length,
      top: envelope.hotspots
        .slice(0, 5)
        .map((h) => ({ path: h.path, gates: h.gateKinds, rank: h.rank })),
    },
    trend: { kinds: envelope.trend.length },
    headroom: { axes: envelope.headroom.length },
    degradations: envelope.degradations,
  };
}

/**
 * Soft-fail dedup: a lookup that cannot complete degrades one group to
 * `create` instead of aborting the whole scan (Story #4678, AC-6 / AC-7).
 *
 * `classifyGroupsAgainstGitHub` stays pure orchestration — it accepts an
 * optional `onDegraded` sink and reports `summary.dedupDegraded`. A search port
 * that throws HTTP 422 for one group must not stop the remaining groups from
 * keeping their real classifications.
 */

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { __testing as auditCli } from '../../../audit-to-stories.js';
import { classifyGroupsAgainstGitHub } from '../dedupe-against-github.js';
import {
  renderFingerprintFooter,
  withFingerprints,
} from '../finding-adapter.js';

const { dedupDegradedWarning } = auditCli;

function auditFinding(dimension, normalisedTitle, file) {
  return { dimension, normalisedTitle, files: file ? [file] : [] };
}
function fakeGroup(key, findings) {
  const stamped = withFingerprints(findings);
  return { groupKey: key, findings: stamped };
}
function footerFor(finding) {
  return renderFingerprintFooter(withFingerprints([finding]));
}

const OPEN_FINDING = auditFinding('security', 'sqli in login', 'src/a.js');
const BAD_FINDING = auditFinding('perf', 'n+1 in report', 'src/b.js');

/**
 * A provider whose fingerprint lookup throws for the finding in `failGroupSha`
 * (simulating an HTTP 422 the endpoint budget could not absorb) and otherwise
 * resolves against an in-memory issue set carrying `footerFor(OPEN_FINDING)`.
 */
function partiallyFailingProvider(failSha) {
  const openBody = `body\n${footerFor(OPEN_FINDING)}\n`;
  return {
    async findIssuesByFingerprint(sha) {
      if (sha === failSha) {
        const err = new Error('Validation Failed: query too long');
        err.status = 422;
        throw err;
      }
      return [{ number: 4182, state: 'OPEN', body: openBody }].filter((i) =>
        i.body.includes(sha),
      );
    },
  };
}

describe('classifyGroupsAgainstGitHub soft-fail', () => {
  it('AC-6: a 422 for one group degrades it to create, others keep their classification', async () => {
    const openGroup = fakeGroup('g-open', [OPEN_FINDING]);
    const badGroup = fakeGroup('g-bad', [BAD_FINDING]);
    const badSha = badGroup.findings[0].fingerprint.full;

    const degraded = [];
    const { classifications, summary } = await classifyGroupsAgainstGitHub({
      groups: [openGroup, badGroup],
      provider: partiallyFailingProvider(badSha),
      onDegraded: (entry) => degraded.push(entry),
    });

    const byKey = Object.fromEntries(
      classifications.map((c) => [c.group.groupKey, c.action]),
    );
    assert.equal(byKey['g-open'], 'skip-open', 'healthy group keeps its match');
    assert.equal(byKey['g-bad'], 'create', 'failed group degrades to create');
    assert.equal(summary.skipOpen, 1);
    assert.equal(summary.create, 1);
    // AC-7: the degrade is reported, not silent.
    assert.equal(summary.dedupDegraded.count, 1);
    assert.equal(summary.dedupDegraded.groups[0].group, 'g-bad');
    assert.match(summary.dedupDegraded.groups[0].reason, /422/);
    assert.equal(degraded.length, 1, 'onDegraded sink fired once');
    assert.equal(degraded[0].group.groupKey, 'g-bad');
  });

  it('reports zero degradations when every lookup completes', async () => {
    const openGroup = fakeGroup('g-open', [OPEN_FINDING]);
    const { summary } = await classifyGroupsAgainstGitHub({
      groups: [openGroup],
      provider: partiallyFailingProvider('never-matches'),
    });
    assert.equal(summary.dedupDegraded.count, 0);
    assert.deepEqual(summary.dedupDegraded.groups, []);
  });
});

describe('dedupDegradedWarning (loud, operator-visible)', () => {
  it('names each affected group and its reason and warns of possible duplicates', () => {
    const msg = dedupDegradedWarning([
      { group: 'g-bad', reason: 'search query rejected (HTTP 422)' },
    ]);
    assert.match(msg, /dedup degraded for 1 group/i);
    assert.match(msg, /g-bad/);
    assert.match(msg, /422/);
    assert.match(msg, /duplicate/i);
  });
});

/**
 * path-canon.js — single canonicalisation authority for every path written
 * into (or compared against) a Mandrel baseline (Story #1891, Epic #1786).
 *
 * This module is the one place baseline path canonicalisation lives. It
 * exposes three helpers tuned to two boundaries (Story #3345 folded the
 * formerly separate `canonicalize-path.js` permissive coercer in here so
 * there is a single import surface):
 *
 *   - `canonicalise(p)` — the **strict** repo-relative canonicaliser. It
 *     rejects input it considers unsafe to key a baseline by, then
 *     normalises what it accepts.
 *   - `assertCanonical(p)` — the **throw-on-reject** writer-boundary check.
 *     It runs the same rejection checks as `canonicalise` but never
 *     transforms the input.
 *   - `canonicalizeBaselinePath(p)` — the **permissive coercer** used by the
 *     refresh service. It never throws on absolute / drive-letter / UNC
 *     input; instead it transforms those shapes into a repo-relative key,
 *     because its caller funnels raw `git diff` and tool output through a
 *     single point that must always yield a canonical key.
 *
 * `canonicalise` enforces, in order:
 *
 *   1. Rejects absolute paths (Windows `C:\...` or POSIX `/...`) — baselines
 *      that key by absolute paths break the moment they're checked out on a
 *      different machine, in a worktree, or in CI.
 *   2. Rejects `..` segments — baselines must not name files outside the
 *      repo root, and the loader's signed-int comparison can otherwise be
 *      fooled by a traversal-shaped key.
 *   3. Strips a leading `.worktrees/<workspace>/` prefix so a refresh run
 *      from inside `.worktrees/story-1891/...` produces the same key as a
 *      refresh from the main checkout. This is the defensive policy that
 *      stops a future worktree-based refresh from reintroducing the
 *      maintainability worktree-prefix regression that prompted Story #1891.
 *   4. Normalises Windows backslashes to forward slashes.
 *   5. Strips a leading `./` for cosmetic stability — `./src/a.js` and
 *      `src/a.js` are the same path and should serialise to the same key.
 *
 * Both `canonicalise` and `canonicalizeBaselinePath` are **idempotent**:
 * feeding either function's output back in produces the same string. Tests
 * pin this property explicitly.
 *
 * `assertCanonical` is the throw-on-reject variant. It runs the same checks
 * but does not transform the input — used at the writer boundary to assert
 * a row's `path` has already been canonicalised by the caller (so the writer
 * never silently rewrites a row's identity).
 *
 * @module lib/baselines/path-canon
 */

const WORKTREE_PREFIX = /^\.worktrees\/[^/\\]+[/\\]/;

/**
 * Test whether `value` is a Windows or POSIX absolute path. Windows absolute
 * paths have a drive letter (`C:`) or start with a backslash-separator
 * (`\\server\share`). POSIX absolute paths start with a forward slash.
 *
 * @param {string} value
 * @returns {boolean}
 */
function isAbsolute(value) {
  if (value.startsWith('/')) return true;
  if (value.startsWith('\\')) return true;
  // Drive-letter form: `C:\...` or `C:/...` or even bare `C:foo` (rare but
  // still absolute in Windows semantics — refuse it).
  if (/^[A-Za-z]:[\\/]?/.test(value)) return true;
  return false;
}

/**
 * Test whether `value` contains a `..` segment. We tokenise on both `/` and
 * `\` so a Windows-shaped path like `src\..\evil.js` is caught before
 * normalisation rewrites the separators.
 *
 * @param {string} value
 * @returns {boolean}
 */
function hasTraversal(value) {
  const parts = value.split(/[/\\]/);
  return parts.some((segment) => segment === '..');
}

/**
 * Canonicalise a path for use as a baseline row key.
 *
 * @param {string} input  A repo-relative path. May use `\` or `/` separators
 *                        and may carry a leading `./` or
 *                        `.worktrees/<workspace>/` prefix.
 * @returns {string}      The canonical, forward-slash, repo-relative form.
 * @throws {TypeError}    When `input` is not a string.
 * @throws {Error}        When `input` is absolute or contains a `..` segment.
 */
export function canonicalise(input) {
  if (typeof input !== 'string') {
    throw new TypeError(
      `path-canon.canonicalise: expected string, got ${typeof input}`,
    );
  }
  if (input.length === 0) {
    throw new Error('path-canon.canonicalise: path must be non-empty');
  }
  if (isAbsolute(input)) {
    throw new Error(
      `path-canon.canonicalise: absolute paths are forbidden in baselines (got "${input}")`,
    );
  }
  if (hasTraversal(input)) {
    throw new Error(
      `path-canon.canonicalise: ".." segments are forbidden in baselines (got "${input}")`,
    );
  }

  // 1. Normalise separators first so the worktree-prefix regex sees a
  //    forward-slash form regardless of platform.
  let working = input.replace(/\\/g, '/');

  // 2. Strip `.worktrees/<workspace>/` prefix (defensive policy — see
  //    module preamble).
  working = working.replace(WORKTREE_PREFIX, '');

  // 3. Strip a leading `./` after worktree-prefix removal so
  //    `./.worktrees/story-1/src/a.js` and `.worktrees/story-1/src/a.js`
  //    converge.
  if (working.startsWith('./')) working = working.slice(2);

  // 4. Collapse any accidental double-slashes introduced by upstream
  //    string concat — leaves leading `/` alone since we've already
  //    rejected absolute paths.
  working = working.replace(/\/{2,}/g, '/');

  if (working.length === 0) {
    throw new Error(
      `path-canon.canonicalise: path collapsed to empty after canonicalisation (got "${input}")`,
    );
  }

  return working;
}

/**
 * Assert that `input` is already in canonical form. Throws on any deviation;
 * never transforms the input. Used at the writer boundary as a defensive
 * check that callers have funnelled their rows through `canonicalise` before
 * handing them to `write()`.
 *
 * @param {string} input
 * @returns {void}
 * @throws {TypeError|Error}
 */
export function assertCanonical(input) {
  if (typeof input !== 'string') {
    throw new TypeError(
      `path-canon.assertCanonical: expected string, got ${typeof input}`,
    );
  }
  if (input.length === 0) {
    throw new Error('path-canon.assertCanonical: path must be non-empty');
  }
  if (isAbsolute(input)) {
    throw new Error(
      `path-canon.assertCanonical: absolute paths are forbidden in baselines (got "${input}")`,
    );
  }
  if (hasTraversal(input)) {
    throw new Error(
      `path-canon.assertCanonical: ".." segments are forbidden in baselines (got "${input}")`,
    );
  }
  if (input.includes('\\')) {
    throw new Error(
      `path-canon.assertCanonical: backslash separators are forbidden in baselines (got "${input}")`,
    );
  }
  if (WORKTREE_PREFIX.test(input)) {
    throw new Error(
      `path-canon.assertCanonical: .worktrees/<workspace>/ prefix is forbidden in baselines (got "${input}")`,
    );
  }
  if (input.startsWith('./')) {
    throw new Error(
      `path-canon.assertCanonical: leading "./" is forbidden in baselines (got "${input}")`,
    );
  }
  if (input.includes('//')) {
    throw new Error(
      `path-canon.assertCanonical: double-slash segments are forbidden in baselines (got "${input}")`,
    );
  }
}

/**
 * Permissively coerce a raw filesystem path into the POSIX, repo-relative
 * key shape used by the Unified Baseline Refresh Service (Story #2192,
 * Epic #2173). Unlike `canonicalise`, this helper never throws on absolute,
 * drive-letter, or UNC input — it transforms those shapes into a
 * repo-relative key because its caller (the refresh service) receives raw
 * paths from `git diff` and tool output and needs a single funnel that
 * always produces a canonical key.
 *
 * Rules, in order:
 *   1. Reject non-string input with `TypeError`.
 *   2. Swap every `\` for `/` so the rest of the pipeline sees a single
 *      separator style regardless of platform.
 *   3. Strip a UNC prefix (`//server/share/`) so paths surfaced by tools
 *      that resolved a network share collapse to a repo-relative key.
 *   4. Strip a Windows drive-letter prefix (`C:` / `C:/`) so paths
 *      surfaced by Windows tools collapse to the same key as the
 *      equivalent Linux path.
 *   5. Strip a single leading `/` so a path that was absolute after
 *      drive-letter stripping becomes repo-relative.
 *   6. Strip a leading `.worktrees/<workspace>/` prefix so a refresh run
 *      from inside a worktree produces the same key as a refresh from the
 *      main checkout. This MUST match the equivalent step in
 *      `canonicalise()` (Story #3695): the strict canonicaliser used by the
 *      per-kind `projectRow` strips this prefix, so the permissive coercer
 *      that builds the diff-scope `scope.files` set MUST strip it too —
 *      otherwise a scored row's path (`src/new.js`) never matches its
 *      worktree-prefixed scope entry (`.worktrees/story-1/src/new.js`) and
 *      a brand-new file's row is silently dropped from the scoped baseline.
 *   7. Strip a leading `./` for cosmetic stability.
 *   8. Collapse any `/{2,}` run to a single `/`.
 *
 * The function is **idempotent**: feeding its own output back in produces
 * the same string. Downstream consumers (the refresh service and the gate
 * reader) rely on this property so a row written on Windows compares equal
 * to the same row written on Linux.
 *
 * @param {string} input  A raw filesystem path. May use `\` or `/`
 *                        separators, may carry a Windows drive letter, may
 *                        be absolute or relative.
 * @returns {string}      The canonical, forward-slash, repo-relative key.
 * @throws {TypeError}    When `input` is not a string.
 */
export function canonicalizeBaselinePath(input) {
  if (typeof input !== 'string') {
    throw new TypeError(
      `canonicalizeBaselinePath: expected string, got ${input === null ? 'null' : typeof input}`,
    );
  }

  // 1. Normalize separators first.
  let working = input.replace(/\\/g, '/');

  // 2. Strip UNC share prefix (`//server/share/...`) before generic
  //    double-slash collapse so the share name is preserved as a regular
  //    path segment, not eaten.
  const uncMatch = working.match(/^\/\/([^/]+)\/([^/]+)(\/|$)/);
  if (uncMatch) {
    working = working.slice(uncMatch[0].length);
  }

  // 3. Strip Windows drive-letter prefix (`C:` or `C:/`).
  working = working.replace(/^[A-Za-z]:\/?/, '');

  // 4. Strip a single leading `/` so an absolute path becomes
  //    repo-relative.
  if (working.startsWith('/')) {
    working = working.replace(/^\/+/, '');
  }

  // 5. Strip a leading `.worktrees/<workspace>/` prefix (Story #3695) so a
  //    worktree-rooted path collapses to the same repo-relative key the
  //    strict `canonicalise()` produces. Without this, a scored row path and
  //    its diff-scope `scope.files` entry diverge inside a worktree and the
  //    scope-aware merge drops brand-new files. Only a single leading
  //    segment is stripped — a legitimate inner `.worktrees/` directory the
  //    user named themselves is preserved (mirrors `canonicalise`).
  working = working.replace(WORKTREE_PREFIX, '');

  // 6. Strip a leading `./`.
  if (working.startsWith('./')) {
    working = working.slice(2);
  }

  // 7. Collapse redundant separators.
  working = working.replace(/\/{2,}/g, '/');

  return working;
}

/**
 * Resolves c8's CLI entry point so callers can spawn it via
 * `process.execPath <c8Cli>` (shell:false) instead of routing through
 * the `npx.cmd` shim, which would force shell:true under
 * CVE-2024-27980's .cmd/.bat policy and re-open CWE-78.
 *
 * `bin/c8.js` is not exported from c8's package.json, so the lookup
 * goes through `package.json` (always in the exports map) and
 * `path.join` to its sibling bin file.
 */

import { createRequire } from 'node:module';
import path from 'node:path';

const require = createRequire(import.meta.url);

export const C8_CLI = path.join(
  path.dirname(require.resolve('c8/package.json')),
  'bin',
  'c8.js',
);

/**
 * Acceptance self-eval accessor (Story #3819, Story #5313).
 *
 * Resolves `.agentrc.json → delivery.acceptanceEval` into the canonical
 * shape the per-Story acceptance self-eval loop consumes. The loop scores
 * the caller-injected change set against each inline `acceptance[]` item,
 * redrafts the unmet items, and re-evaluates — capped at `maxRounds`
 * redraft rounds, then escalates to `agent::blocked` when criteria remain
 * unmet.
 *
 * Story #5313 dropped the hard ceiling (`ACCEPTANCE_EVAL_MAX_ROUNDS_CEILING`)
 * and the floor-of-one clamp: `maxRounds` is any non-negative integer, and
 * `0` means the verdict is scored **once** with no redraft round. The
 * scoring pass itself is always on — there is intentionally no `enabled`
 * flag (hard cutover per `rules/git-conventions.md`); only the redraft
 * budget is tunable.
 */

/**
 * Default redraft-round budget applied when `.agentrc.json` omits
 * `delivery.acceptanceEval.maxRounds`. Frozen so downstream callers cannot
 * mutate the resolver's defaults across processes.
 *
 * Keep in lockstep with the schema mirror in
 * `agentrc.schema.json → $defs.acceptanceEval` and the AJV schema in
 * `config-settings-schema-delivery.js → ACCEPTANCE_EVAL_SCHEMA`.
 */
export const ACCEPTANCE_EVAL_DEFAULTS = Object.freeze({
  maxRounds: 2,
});

/**
 * Normalize a candidate round count: a non-negative integer is taken as-is
 * (including `0`); anything else — negative, non-integer, non-finite,
 * missing — falls back to the documented default.
 *
 * @param {unknown} value
 * @param {number} fallback
 * @returns {number}
 */
function normalizeRounds(value, fallback) {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0
    ? value
    : fallback;
}

/**
 * Read the merged acceptance-eval block. Returns the canonical shape:
 *
 *   { maxRounds: number }  // non-negative integer; 0 = scored once
 *
 * @param {object | null | undefined} config
 * @returns {{ maxRounds: number }}
 */
export function getAcceptanceEval(config) {
  const user = config?.delivery?.acceptanceEval ?? {};
  return {
    maxRounds: normalizeRounds(
      user.maxRounds,
      ACCEPTANCE_EVAL_DEFAULTS.maxRounds,
    ),
  };
}

/**
 * `delivery.worktreeIsolation` accessor + framework defaults.
 *
 * Several consumers read this block directly (runtime.js,
 * worktree-manager.js, workspace-provisioner.js) and previously each
 * carried its own fallback constant. Centralising the defaults here
 * lets `applyDefaults()` in `config-resolver.js` enrich the canonical
 * block once, so consumers never see `undefined` for a defaulted field
 * (which previously meant, e.g., `Boolean(undefined) === false`
 * silently disabling worktrees when the operator omitted the block).
 */

/**
 * Default `nodeModulesStrategy`, platform-aware (Story #4249).
 *
 * darwin/linux default to `clone` — a copy-on-write (clonefile/reflink) clone
 * of the donor's `node_modules` that is effectively free in time and disk on
 * APFS / reflink-capable filesystems, with a clean fall-back to `per-worktree`
 * on any failure (unsupported fs, cross-volume, etc.). Windows has no reflink
 * equivalent on this path, so it keeps the `per-worktree` install default.
 *
 * @param {NodeJS.Platform} [platform]
 * @returns {'clone' | 'per-worktree'}
 */
export function defaultNodeModulesStrategy(platform = process.platform) {
  return platform === 'win32' ? 'per-worktree' : 'clone';
}

export const WORKTREE_ISOLATION_DEFAULTS = Object.freeze({
  enabled: true,
  root: '.worktrees',
  nodeModulesStrategy: defaultNodeModulesStrategy(),
  primeFromPath: null,
  allowSymlinkOnWindows: false,
  reapOnSuccess: true,
  // Gitignored workspace files copied into each new worktree. Includes the
  // operator's local-override files (`.agentrc.local.json`,
  // `.agents/instructions.local.md`) so a worktree-isolated agent honors the
  // §1.E local-override contract instead of silently falling back to the
  // committed `.agentrc.json` placeholders — the gap that left
  // `github.operatorHandle` unset inside worktrees and broke Story-lease
  // release at close. Missing sources are skipped by the provisioner, so
  // listing files that may be absent is safe. Keep in sync with
  // `DEFAULT_WORKSPACE_FILES` in `../workspace-provisioner.js`.
  bootstrapFiles: Object.freeze([
    '.env',
    '.mcp.json',
    '.agentrc.local.json',
    '.agents/instructions.local.md',
  ]),
});

/**
 * Read the merged `delivery.worktreeIsolation` block, applying framework
 * defaults for any field the operator omitted. Accepts the full resolved
 * config, the bare delivery bag, or the bare worktreeIsolation bag.
 *
 * @param {object | null | undefined} config
 * @returns {typeof WORKTREE_ISOLATION_DEFAULTS}
 */
export function getWorktreeIsolation(config) {
  const wi =
    config?.delivery?.worktreeIsolation ??
    config?.worktreeIsolation ??
    config ??
    {};
  return {
    enabled:
      typeof wi.enabled === 'boolean'
        ? wi.enabled
        : WORKTREE_ISOLATION_DEFAULTS.enabled,
    root: wi.root ?? WORKTREE_ISOLATION_DEFAULTS.root,
    nodeModulesStrategy: wi.nodeModulesStrategy ?? defaultNodeModulesStrategy(),
    primeFromPath:
      wi.primeFromPath === undefined
        ? WORKTREE_ISOLATION_DEFAULTS.primeFromPath
        : wi.primeFromPath,
    allowSymlinkOnWindows:
      typeof wi.allowSymlinkOnWindows === 'boolean'
        ? wi.allowSymlinkOnWindows
        : WORKTREE_ISOLATION_DEFAULTS.allowSymlinkOnWindows,
    reapOnSuccess:
      typeof wi.reapOnSuccess === 'boolean'
        ? wi.reapOnSuccess
        : WORKTREE_ISOLATION_DEFAULTS.reapOnSuccess,
    bootstrapFiles: Array.isArray(wi.bootstrapFiles)
      ? wi.bootstrapFiles
      : [...WORKTREE_ISOLATION_DEFAULTS.bootstrapFiles],
  };
}

