test('a scoped, breaking-marked subject still yields its type', () => {
  // `parseConventionalType` is module-private; `pickDominantType` is the seam
  // that reads it, so the scope/`!` tolerance is pinned through that.
  assert.equal(pickDominantType(['chore(gates)!: x']), 'chore');
  assert.equal(pickDominantType(['Rename the package']), null);
});

/**
 * story-deliver-terminal.js — the one terminal envelope every Story
 * close-and-land invocation emits, and the shared next-command vocabulary
 * (Story #4543).
 *
 * Before this module the delivery tail had **two** divergent return
 * contracts, both prose and neither validated:
 * `.agents/workflows/helpers/deliver-story.md` defined one shape and
 * `.agents/agents/story-worker.md` a different one, so a caller could not
 * distinguish a landed Story from a parked one without re-probing GitHub.
 * `story-deliver-terminal.schema.json` is now the SSOT both docs reference
 * rather than restate, and this module is its only writer.
 *
 * Two exports carry the contract:
 *
 *   - {@link buildTerminalEnvelope} assembles and **validates** the envelope.
 *     It throws on a schema violation rather than emitting a malformed
 *     terminal: a silently-wrong terminal is exactly the failure this Story
 *     exists to eliminate, so failing loudly at the writer is the point.
 *   - {@link NEXT_COMMANDS} is the next-command vocabulary shared with
 *     `deliver-recover.js`, so a `pending` envelope and a recovery probe
 *     name the same command for the same state instead of inventing two
 *     dialects for one condition.
 *
 * `TERMINAL_EXIT_CODES` maps status → process exit code. `pending` gets its
 * **own** code (3) precisely so a caller can tell "slow CI, resume me" from
 * "hard block, come look" without parsing stdout — the distinction the
 * pre-#4543 pipeline collapsed by treating budget exhaustion as a block.
 */

import nodeFs from 'node:fs';
import path from 'node:path';
import { storyTerminalEnvelopePath } from '../config/temp-paths.js';
import { resolveConfig } from '../config-resolver.js';
import { validateTerminalEnvelope } from './story-deliver-terminal-schema.js';

// Re-exported so the schema split stays an implementation detail: every
// consumer still reaches the validator through the envelope module that owns
// the contract.
export { validateTerminalEnvelope };

export const TERMINAL_ENVELOPE_KIND = 'story-deliver-terminal';

/**
 * status → process exit code.
 *
 * `pending` is **3**, not 0 and not 1. Zero would tell a headless caller the
 * Story landed when it did not; one would conflate a resumable slow-CI wait
 * with a hard block and send the operator to diagnose branch protection that
 * is working fine. A distinct code is what lets `/mandrel-deliver` resume without
 * classifying.
 */
export const TERMINAL_EXIT_CODES = Object.freeze({
  landed: 0,
  pending: 3,
  blocked: 1,
  failed: 1,
  /**
   * `escalated` reuses **2**, the code `/deliver-light` already documents for
   * "the gate did not proceed light" — the escalation is that outcome made
   * terminal, not a new one, so giving it a fresh code would fork a vocabulary
   * callers already branch on. It stays distinct from `landed` (nothing was
   * delivered) and from `blocked`/`failed` (nothing is wrong — the work simply
   * belongs to `/mandrel-plan`).
   */
  escalated: 2,
});

export const TERMINAL_STATUSES = Object.freeze([
  'landed',
  'pending',
  'blocked',
  'failed',
  'escalated',
]);

/** Cap on the prompt echoed into an escalation's `/mandrel-plan` next command. */
const PLAN_PROMPT_MAX = 200;

/**
 * Render an operator prompt safe to sit inside the double quotes of the
 * `/mandrel-plan "<prompt>"` next command: collapse newlines (a next command is one
 * line by contract), escape backslashes and double quotes so the quoting
 * cannot be broken out of, and cap the length so a long prompt does not turn
 * the envelope into a transcript. Total — a non-string yields the empty
 * string, which the escalation builder rejects rather than emitting.
 *
 * @param {unknown} prompt
 * @returns {string}
 */
function quoteForPlan(prompt) {
  const text =
    typeof prompt === 'string' ? prompt.replace(/\s+/g, ' ').trim() : '';
  const capped =
    text.length > PLAN_PROMPT_MAX
      ? `${text.slice(0, PLAN_PROMPT_MAX - 1).trimEnd()}…`
      : text;
  return capped.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

/**
 * The shared next-command vocabulary. Every producer of a "what now?"
 * answer — the `pending` terminal envelope, an `escalated` one, and
 * `deliver-recover.js` — builds its command from here, so the surfaces never
 * drift into naming different commands for the same observed state.
 */
export const NEXT_COMMANDS = Object.freeze({
  /**
   * Resume a bounded merge wait that expired with the PR still in flight.
   *
   * `--wait` is load-bearing: without it the confirm CLI probes once and
   * answers `pending` again, so the cumulative-budget give-up never fires and
   * a wedged PR is never escalated to anyone.
   */
  resumeLand: (storyId) =>
    `node .agents/scripts/single-story-confirm-merge.js --story ${storyId} --wait`,
  /** Confirm a merged-but-mislabelled Story (the idempotent flip + tail). */
  confirmMerge: (storyId) =>
    `node .agents/scripts/single-story-confirm-merge.js --story ${storyId}`,
  /** Enter the red-CI fix loop against the failing PR. */
  watchCi: (storyId, prNumber) =>
    `node .agents/scripts/pr-watch-with-update.js --pr ${prNumber} --story ${storyId}`,
  /** Re-run close for a Story whose PR was never opened. */
  close: (storyId) =>
    `node .agents/scripts/single-story-close.js --story ${storyId}`,
  /** Resume implementation in the Story worktree. */
  implement: (storyId) =>
    `node .agents/scripts/single-story-init.js --story ${storyId}`,
  /** Re-assert a drifted Projects v2 Status column. */
  resync: (storyId) =>
    `node .agents/scripts/resync-status-column.js --story ${storyId}`,
  /** Probe a stranded Story and print its single next command. */
  recover: (storyId) =>
    `node .agents/scripts/deliver-recover.js --story ${storyId}`,
  /**
   * Hand over-scope work to `/mandrel-plan` — the next command of an `escalated`
   * terminal (Story #4746).
   *
   * The only entry here that is a slash command rather than a script, and
   * deliberately so: the other entries resume a Story that exists, while this
   * one names work that has no Story yet and needs planning before it can have
   * one. It is quoted for a shell but addressed to a **fresh session** — see
   * the workflow's escalation section for why running it in the escalating
   * session is forbidden.
   */
  escalateToPlan: (prompt) => `/mandrel-plan "${quoteForPlan(prompt)}"`,
});

/**
 * Drop `undefined`-valued keys so the schema's `additionalProperties: false`
 * and its nullable unions both stay satisfiable from one optional-argument
 * builder signature.
 *
 * @param {object} obj
 * @returns {object}
 */
function compact(obj) {
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (v !== undefined) out[k] = v;
  }
  return out;
}

/**
 * Assemble the terminal envelope and validate it before returning.
 *
 * Throws a `TypeError` naming the schema violations when the assembled
 * object does not validate. That is deliberate: the whole point of the
 * envelope is that a caller can trust its status without re-probing
 * GitHub, so emitting a *malformed* one would reintroduce the ambiguity
 * this replaces.
 *
 * A schema that cannot be READ is the opposite case and does not throw —
 * see {@link validateTerminalEnvelope}. "This envelope is wrong" is worth
 * failing on; "I could not check this envelope" is not worth destroying
 * the return contract over.
 *
 * @param {object} args
 * @param {number|null} args.storyId `null` only for an `escalated` terminal,
 *   which by construction never authored a Story.
 * @param {'landed'|'pending'|'blocked'|'failed'|'escalated'} args.status
 * @param {string} args.phase
 * @param {string} [args.storyBranch]
 * @param {string} [args.baseBranch]
 * @param {object|null} [args.pr]
 * @param {object} [args.gates]
 * @param {object|null} [args.tail]
 * @param {object|null} [args.blocked]
 * @param {object|null} [args.failure]
 * @param {object|null} [args.escalation]
 * @param {string|null} [args.nextCommand]
 * @param {number} args.elapsedSeconds
 * @param {object|null} [args.waitBudget]
 * @param {string} [args.timestamp]
 * @param {{ schema: object|null, error: string|null }} [args.schemaSource]
 *   Test seam; never passed in production. Not part of the envelope — the
 *   envelope is assembled from named fields only.
 * @returns {object} The validated envelope.
 */
export function buildTerminalEnvelope({
  storyId,
  status,
  phase,
  storyBranch,
  baseBranch,
  pr,
  gates,
  tail,
  blocked,
  failure,
  escalation,
  nextCommand,
  elapsedSeconds = 0,
  waitBudget,
  timestamp = new Date().toISOString(),
  schemaSource,
}) {
  const envelope = compact({
    kind: TERMINAL_ENVELOPE_KIND,
    // `Number(null)` is 0, which would quietly satisfy nothing and confuse
    // everything — a nullish storyId stays null and lets the schema decide
    // whether this status is allowed to omit one.
    storyId: storyId === null || storyId === undefined ? null : Number(storyId),
    status,
    phase,
    storyBranch: storyBranch ?? null,
    baseBranch: baseBranch ?? null,
    pr: pr ?? null,
    gates,
    tail: tail ?? null,
    blocked: blocked ?? null,
    failure: failure ?? null,
    escalation: escalation ?? null,
    nextCommand: nextCommand ?? null,
    elapsedSeconds: Math.max(0, Number(elapsedSeconds) || 0),
    waitBudget: waitBudget ?? null,
    timestamp,
  });

  // Passing `{ schemaSource }` unconditionally is safe: an `undefined`
  // property value is exactly what triggers the destructuring default on the
  // other side, so production still gets the eagerly-loaded module source.
  const { valid, errors } = validateTerminalEnvelope(envelope, {
    schemaSource,
  });
  if (!valid) {
    throw new TypeError(
      `buildTerminalEnvelope: assembled envelope violates story-deliver-terminal.schema.json:\n` +
        errors.map((e) => `  - ${e}`).join('\n'),
    );
  }
  return envelope;
}

/**
 * Build the `escalated` terminal — the one envelope emitted before a Story
 * exists (Story #4746).
 *
 * `/deliver-light`'s suitability gate already decided correctly when it
 * overrode a `lite` self-verdict on shape; what it lacked was an outcome a
 * session could not walk past. A mandrel-bench 2.13.0 light-arm run did
 * exactly that — it read the gate's `escalate-plan`, then invoked `/mandrel-plan`
 * in the same session and delivered. The continuation was not harmless:
 * planning inside a session already framed as small work authored ONE Story
 * against the scenario's 3-5 contract, where a fresh `/mandrel-plan` session on the
 * identical seed authored four. Escalation silently produced the very
 * under-decomposition the guard exists to prevent.
 *
 * So the outcome is a validated envelope with its own exit code, naming the
 * `/mandrel-plan` command that owns the work, and asserting per artifact that nothing
 * was started. Every guarantee here is enforced by the schema rather than by
 * prose: `storyId` must be null, `escalation.created.*` are pinned `false`.
 *
 * @param {{
 *   prompt: string,
 *   reasons?: string[],
 *   elapsedSeconds?: number,
 *   timestamp?: string,
 * }} args
 * @returns {object} The validated `escalated` envelope.
 */
export function buildEscalationTerminal({
  prompt,
  reasons,
  elapsedSeconds = 0,
  timestamp,
}) {
  const quoted = quoteForPlan(prompt);
  if (quoted === '') {
    // An escalation whose next command is `/mandrel-plan ""` hands the operator
    // nothing — the same walk-past-able non-outcome in envelope clothing.
    throw new TypeError(
      'buildEscalationTerminal: a non-empty prompt is required — the escalated terminal exists to name the /mandrel-plan invocation that owns the work',
    );
  }
  const recorded = (Array.isArray(reasons) ? reasons : []).filter(
    (r) => typeof r === 'string' && r.trim() !== '',
  );
  return buildTerminalEnvelope({
    storyId: null,
    status: 'escalated',
    phase: 'suitability-gate',
    escalation: {
      reasons:
        recorded.length > 0
          ? recorded
          : [
              'predicted scope exceeds the light ceilings — escalate to /mandrel-plan',
            ],
      // Not computed from anything: the escalation path returns before the
      // receipt/init call sites, so these are the assertion that it did.
      created: { receiptStory: false, storyBranch: false, worktree: false },
    },
    nextCommand: NEXT_COMMANDS.escalateToPlan(prompt),
    elapsedSeconds,
    ...(timestamp === undefined ? {} : { timestamp }),
  });
}

/**
 * Resolve the process exit code for a terminal envelope.
 *
 * @param {object} envelope
 * @returns {number}
 */
export function exitCodeForTerminal(envelope) {
  return TERMINAL_EXIT_CODES[envelope?.status] ?? 1;
}

/** The markers a caller scans stdout for to recover the envelope. */
export const TERMINAL_BEGIN_MARKER = '--- STORY DELIVER TERMINAL ---';
export const TERMINAL_END_MARKER = '--- END TERMINAL ---';

/**
 * Resolve the repo config, or `undefined` when it cannot be read.
 *
 * An unreadable `.agentrc.json` must not cost the run its envelope copy: the
 * path helpers fall back to the framework-default temp root, which is still a
 * far better outcome than no artifact at all.
 *
 * @param {typeof resolveConfig} resolveConfigImpl
 * @returns {object|undefined}
 */
function tolerantConfig(resolveConfigImpl) {
  try {
    return resolveConfigImpl();
  } catch {
    return undefined;
  }
}

/**
 * Persist a terminal envelope beside its Story's gate log (Story #4816).
 *
 * Stdout is a channel with exactly one reader — the turn that launched the
 * close — and that reader is not always still listening. A `story-worker`
 * that reports progress and ends its turn while the close it started is
 * mid-gate-chain is behaving reasonably, but the envelope it never relayed is
 * gone: the router then has to reconstruct the Story's state from labels, and
 * `deliver-recover.js` used to answer that reconstruction with
 * "Implementation never finished" — false, and its re-init suggestion can put
 * a second close on one PR. Observed four times across three workers in one
 * consumer run. The file is the second channel, and it outlives the turn.
 *
 * **Best-effort by construction.** Every failure path returns `null`: a
 * delivery must never turn a landed PR into a crash because a temp directory
 * was unwritable. The stdout envelope above is the contract; this is a copy.
 *
 * **Atomic by construction.** The payload is written to a pid-scoped
 * temporary name and renamed into place, because the reader that matters most
 * is a router polling during a live close — a half-written file would hand it
 * a parse error at exactly the moment it is trying to avoid guessing.
 *
 * A null `storyId` (the `escalated` terminal, which by construction never
 * authored a Story) has nowhere to be filed and writes nothing.
 *
 * `config` is optional and resolved lazily when absent. Two of the emit sites
 * are `catch` blocks that crashed before any config was resolved, and those
 * are precisely the runs whose envelope is most worth keeping — so the temp
 * root is looked up here rather than left at the framework default, which
 * would file the artifact where a consumer's router never looks (and where
 * the retention purge would never reap it).
 *
 * @param {object} envelope A validated terminal envelope.
 * @param {{
 *   config?: object,
 *   fsImpl?: typeof nodeFs,
 *   resolveConfigImpl?: typeof resolveConfig,
 * }} [deps]
 * @returns {string|null} The path written, or `null` when nothing was.
 */
export function persistTerminalEnvelope(
  envelope,
  { config, fsImpl = nodeFs, resolveConfigImpl = resolveConfig } = {},
) {
  const storyId = envelope?.storyId;
  if (!Number.isInteger(storyId) || storyId <= 0) return null;
  let tmpPath = null;
  try {
    const resolved = config ?? tolerantConfig(resolveConfigImpl);
    const target = storyTerminalEnvelopePath(storyId, resolved);
    fsImpl.mkdirSync(path.dirname(target), { recursive: true });
    tmpPath = `${target}.${process.pid}.tmp`;
    fsImpl.writeFileSync(tmpPath, `${JSON.stringify(envelope)}\n`, 'utf8');
    fsImpl.renameSync(tmpPath, target);
    return target;
  } catch {
    // A rename that never ran leaves the scratch file behind; drop it rather
    // than accumulating one per failed close.
    if (tmpPath) {
      try {
        fsImpl.rmSync(tmpPath, { force: true });
      } catch {
        // Nothing left to try — this whole path is already best-effort.
      }
    }
    return null;
  }
}

/**
 * Write a terminal envelope to stdout, between its markers, and persist a
 * copy to disk.
 *
 * **Deliberately not `Logger.info`.** The envelope is this CLI's
 * machine-readable contract — every invocation emits exactly ONE, and a
 * headless caller parses it out of stdout to decide what happened.
 * `Logger.info` is level-gated, so under the documented
 * `AGENT_LOG_LEVEL=silent` (execution-reference § Log-level control) the
 * envelope silently vanished and the
 * caller got a bare exit code: precisely the "no envelope at all" outcome
 * Story #4543 exists to remove. A contract payload must not be suppressible
 * by a verbosity knob.
 *
 * Single home for the marker format so the four emit sites (the runner's
 * terminal, the close CLI's failed-terminal catch, and both confirm-CLI
 * paths) cannot drift apart — and, since Story #4816, the single home for the
 * on-disk copy too, so no emit path can persist and another forget.
 * {@link persistTerminalEnvelope} runs **first**: a caller that has read the
 * markers off stdout can then rely on the file already being there.
 *
 * @param {object} envelope
 * @param {{
 *   write?: (s: string) => void,
 *   config?: object,
 *   persist?: typeof persistTerminalEnvelope,
 * }} [opts] `write` and `persist` are test seams; `config` resolves the
 *   artifact's temp root and is threaded from whichever emit site holds one.
 * @returns {void}
 */
export function emitTerminalEnvelope(
  envelope,
  {
    write = (s) => process.stdout.write(s),
    config,
    persist = persistTerminalEnvelope,
  } = {},
) {
  // Belt and braces around a copy: `persistTerminalEnvelope` already swallows
  // its own failures, but the stdout envelope is the CONTRACT and the disk
  // copy is a convenience. Nothing in the secondary path — including a future
  // injected `persist` — may cost the caller the primary one.
  try {
    persist(envelope, { config });
  } catch {
    // Intentionally silent: see above.
  }
  // Story #4685 — compact (not 2-space pretty) JSON. The envelope is a
  // machine contract callers recover with `JSON.parse`, so pretty-printing
  // only adds turn-resident bytes without helping any consumer.
  write(
    `\n${TERMINAL_BEGIN_MARKER}\n${JSON.stringify(envelope)}\n${TERMINAL_END_MARKER}\n`,
  );
}

/**
 * Map a `runConfirmMergePhase` outcome onto the schema-validated terminal
 * envelope (Story #4543). One writer, one shape — the two prose contracts
 * this replaces disagreed with each other precisely because each surface
 * assembled its own.
 *
 * @returns {object} A validated `story-deliver-terminal` envelope.
 */
export function terminalFromWaitOutcome({
  waitOutcome,
  storyId,
  storyBranch,
  baseBranch,
  prNumber,
  prUrl,
  autoMergeEnabled,
  gates,
  elapsedSeconds,
}) {
  const prBase = {
    number: prNumber,
    url: prUrl ?? null,
    autoMergeEnabled: Boolean(autoMergeEnabled),
  };
  const common = {
    storyId,
    storyBranch,
    baseBranch,
    gates,
    elapsedSeconds,
  };

  if (waitOutcome.terminal === 'landed') {
    return buildTerminalEnvelope({
      ...common,
      status: 'landed',
      phase: 'post-land',
      pr: {
        ...prBase,
        state: 'MERGED',
        // The observed rollup, not an assumed 'success' — a merge can land by
        // admin override or with non-required checks red.
        checksStatus: waitOutcome.prProbe?.checksStatus ?? null,
      },
      tail: waitOutcome.tail,
      nextCommand: null,
    });
  }

  if (waitOutcome.terminal === 'pending') {
    return buildTerminalEnvelope({
      ...common,
      status: 'pending',
      phase: 'confirm-merge',
      pr: {
        ...prBase,
        state: waitOutcome.prProbe?.state ?? 'OPEN',
        checksStatus: waitOutcome.prProbe?.checksStatus ?? null,
      },
      waitBudget: waitOutcome.waitBudget,
      nextCommand: NEXT_COMMANDS.resumeLand(storyId),
    });
  }

  // blocked — the classifier already named the class and the friction
  // comment already carries the class-specific remediation, so the next
  // command mirrors it rather than inventing a second opinion.
  const nextCommand =
    waitOutcome.blockClass === 'checks-failed'
      ? NEXT_COMMANDS.watchCi(storyId, prNumber)
      : waitOutcome.blockClass === 'merged-flip-failed'
        ? NEXT_COMMANDS.confirmMerge(storyId)
        : NEXT_COMMANDS.recover(storyId);
  return buildTerminalEnvelope({
    ...common,
    status: 'blocked',
    phase: 'confirm-merge',
    pr: {
      ...prBase,
      state: waitOutcome.prProbe?.state ?? null,
      checksStatus: waitOutcome.prProbe?.checksStatus ?? null,
    },
    blocked: {
      blockClass: waitOutcome.blockClass,
      reason: waitOutcome.reason,
      frictionCommentId: waitOutcome.frictionCommentId ?? null,
    },
    nextCommand,
  });
}

/**
 * resolve-selection.js — scenario-selection resolver for the agent-driven
 * QA harness (Epic #3214, Story #3296).
 *
 * The harness is invoked with a single selector that scopes a sweep to a
 * concrete set of `.feature` files (and, for tag selectors, the specific
 * scenarios within them) under the contract's `featureRoot`. This module
 * turns one of three selector shapes into that concrete set:
 *
 *   - **feature id** — `{ kind: 'feature', id: 'login' }` resolves to the
 *     single `.feature` file whose path stem (basename without the
 *     `.feature` extension) equals the id, or whose `featureRoot`-relative
 *     POSIX path (with or without the extension) equals the id. Matching is
 *     exact and case-insensitive; ambiguous ids (more than one match) throw.
 *
 *   - **tag expression** — `{ kind: 'tag', expression: '@smoke and not @wip' }`
 *     resolves to the scenario set whose tag list satisfies the boolean
 *     expression. The expression grammar is the cucumber-common subset:
 *     `@tag` atoms, `and` / `or` / `not` operators (case-insensitive), and
 *     parentheses. A scenario inherits no implicit tags; only the tags the
 *     scanner attached to it (feature-level + scenario-level, as collected
 *     by `parseFeatureBody`) participate.
 *
 *   - **domain** — `{ kind: 'domain', name: 'billing' }` resolves to every
 *     scenario under the `featureRoot`-relative subdirectory `name`. A
 *     domain is a first-level (or nested) directory grouping beneath the
 *     feature root; the selector matches any scenario whose file lives at
 *     or below `<featureRoot>/<name>/`.
 *
 * Determinism is load-bearing — the QA harness re-runs the same selector
 * across sweeps and must scope the identical scenario set each time. All
 * outputs are sorted by `(file, line)` so the order never depends on
 * filesystem iteration order.
 *
 * This module is pure resolution: it does no browser work, reads no config
 * beyond the `featureRoot` passed in, and never mutates state. The harness
 * workflow (Story #3297) consumes the resolved set; this layer only answers
 * "which scenarios does this selector name?".
 */

import path from 'node:path';

import { listFeatureFiles, scanBddScenarios } from '../bdd-scenario-scanner.js';

/**
 * Normalise a path to POSIX separators so `featureRoot`-relative matching
 * behaves identically on Windows and POSIX hosts.
 *
 * @param {string} p
 * @returns {string}
 */
function toPosix(p) {
  return p.split(path.sep).join('/');
}

/**
 * Compute a scenario's `featureRoot`-relative POSIX path. Used by the
 * feature-id and domain matchers so selectors are written against the
 * stable, repo-relative shape rather than absolute worktree paths.
 *
 * @param {string} featureRoot - Absolute path to the feature root.
 * @param {string} file - Absolute path to a `.feature` file.
 * @returns {string} POSIX-style path relative to `featureRoot`.
 */
function relFromRoot(featureRoot, file) {
  return toPosix(path.relative(featureRoot, file));
}

/**
 * Strip the trailing `.feature` extension (case-insensitive) from a
 * relative path, leaving the path stem the feature-id selector matches on.
 *
 * @param {string} relPath
 * @returns {string}
 */
function stripFeatureExt(relPath) {
  return relPath.replace(/\.feature$/i, '');
}

// ---------------------------------------------------------------------------
// Tag-expression evaluation
// ---------------------------------------------------------------------------

/**
 * Classify a single matched lexeme into a token. `@tag` atoms keep their
 * raw value; `(` / `)` / `and` / `or` / `not` produce structural tokens.
 * Anything else is a malformed expression and throws.
 *
 * @param {string} raw
 * @returns {{ type: string, value?: string }}
 */
function classifyToken(raw) {
  if (raw === '(' || raw === ')') {
    return { type: raw };
  }
  if (raw.startsWith('@')) {
    return { type: 'tag', value: raw };
  }
  const lower = raw.toLowerCase();
  if (lower === 'and' || lower === 'or' || lower === 'not') {
    return { type: lower };
  }
  throw new Error(
    `[resolve-selection] unknown operator "${raw}" in tag expression`,
  );
}

/**
 * Tokenise a cucumber-style tag expression into a flat token stream.
 * Recognised tokens: `(`, `)`, `and`, `or`, `not`, and `@tag` atoms.
 * Whitespace separates tokens; parentheses need no surrounding space.
 *
 * @param {string} expression
 * @returns {Array<{ type: string, value?: string }>}
 */
function tokenizeTagExpression(expression) {
  const tokens = [];
  const re = /\s*(\(|\)|@[\w-]+|[A-Za-z]+)/g;
  let lastIndex = 0;
  for (
    let match = re.exec(expression);
    match !== null;
    match = re.exec(expression)
  ) {
    // Guard against runs of unmatched garbage between tokens.
    const between = expression.slice(lastIndex, match.index).trim();
    if (between.length > 0) {
      throw new Error(
        `[resolve-selection] unexpected token "${between}" in tag expression`,
      );
    }
    lastIndex = re.lastIndex;
    tokens.push(classifyToken(match[1]));
  }
  const tail = expression.slice(lastIndex).trim();
  if (tail.length > 0) {
    throw new Error(
      `[resolve-selection] unexpected token "${tail}" in tag expression`,
    );
  }
  return tokens;
}

/**
 * Recursive-descent parser for the tag-expression grammar:
 *
 *   expr   := term  ( 'or'  term  )*
 *   term   := factor( 'and' factor)*
 *   factor := 'not' factor | '(' expr ')' | tag
 *
 * Produces a predicate `(tagSet: Set<string>) => boolean`. Tag atoms match
 * case-insensitively against the scenario's tag set (which carries the
 * leading `@`).
 *
 * @param {string} expression
 * @returns {(tags: Set<string>) => boolean}
 */
export function parseTagExpression(expression) {
  if (typeof expression !== 'string' || expression.trim().length === 0) {
    throw new Error(
      '[resolve-selection] tag expression must be a non-empty string',
    );
  }
  const tokens = tokenizeTagExpression(expression);
  let pos = 0;

  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parseExpr() {
    let left = parseTerm();
    while (peek() && peek().type === 'or') {
      next();
      const right = parseTerm();
      const l = left;
      left = (tags) => l(tags) || right(tags);
    }
    return left;
  }

  function parseTerm() {
    let left = parseFactor();
    while (peek() && peek().type === 'and') {
      next();
      const right = parseFactor();
      const l = left;
      left = (tags) => l(tags) && right(tags);
    }
    return left;
  }

  function parseFactor() {
    const tok = peek();
    if (!tok) {
      throw new Error('[resolve-selection] unexpected end of tag expression');
    }
    if (tok.type === 'not') {
      next();
      const operand = parseFactor();
      return (tags) => !operand(tags);
    }
    if (tok.type === '(') {
      next();
      const inner = parseExpr();
      const close = next();
      if (!close || close.type !== ')') {
        throw new Error('[resolve-selection] missing closing parenthesis');
      }
      return inner;
    }
    if (tok.type === 'tag') {
      next();
      const wanted = tok.value.toLowerCase();
      return (tags) => tags.has(wanted);
    }
    throw new Error(
      `[resolve-selection] unexpected token "${tok.type}" in tag expression`,
    );
  }

  const predicate = parseExpr();
  if (pos !== tokens.length) {
    throw new Error('[resolve-selection] trailing tokens in tag expression');
  }
  return predicate;
}

/**
 * Build a lower-cased tag `Set` for a scanned scenario so the predicate can
 * test membership case-insensitively.
 *
 * @param {{ tags?: string[] }} scenario
 * @returns {Set<string>}
 */
function tagSetOf(scenario) {
  return new Set((scenario.tags ?? []).map((t) => t.toLowerCase()));
}

// ---------------------------------------------------------------------------
// Public resolver
// ---------------------------------------------------------------------------

/**
 * Sort scanned scenarios deterministically by `(file, line)`.
 *
 * @param {Array<{ file: string, line: number }>} scenarios
 * @returns {Array<object>}
 */
function sortScenarios(scenarios) {
  return scenarios
    .slice()
    .sort((a, b) =>
      a.file === b.file ? a.line - b.line : a.file < b.file ? -1 : 1,
    );
}

/**
 * Resolve a selector into a concrete scenario set under `featureRoot`.
 *
 * @param {object} args
 * @param {string} args.featureRoot - Absolute path to the contract's
 *   `.feature` root. The harness prefers the `qa.featureRoot` contract
 *   value over auto-detection; this resolver takes it as given.
 * @param {object} args.selector - One of the three selector shapes:
 *   `{ kind: 'feature', id }`, `{ kind: 'tag', expression }`, or
 *   `{ kind: 'domain', name }`.
 * @param {{ logger?: object }} [opts]
 * @returns {{ kind: string, featureRoot: string, files: string[], scenarios: Array<object> }}
 *   `files` is the deduped, sorted set of absolute `.feature` paths the
 *   selection touches; `scenarios` is the sorted scenario rows (for tag
 *   selection it is the satisfying subset, for feature/domain it is every
 *   scenario in the matched files).
 */
export function resolveSelection(args = {}, opts = {}) {
  const { featureRoot, selector } = args;
  if (typeof featureRoot !== 'string' || featureRoot.length === 0) {
    throw new Error('[resolve-selection] featureRoot is required');
  }
  if (!selector || typeof selector !== 'object') {
    throw new Error('[resolve-selection] selector is required');
  }

  switch (selector.kind) {
    case 'feature':
      return resolveFeature(featureRoot, selector, opts);
    case 'tag':
      return resolveTag(featureRoot, selector, opts);
    case 'domain':
      return resolveDomain(featureRoot, selector, opts);
    default:
      throw new Error(
        `[resolve-selection] unknown selector kind "${selector.kind}"`,
      );
  }
}

function resolveFeature(featureRoot, selector, opts) {
  const id = selector.id;
  if (typeof id !== 'string' || id.trim().length === 0) {
    throw new Error(
      '[resolve-selection] feature selector requires a non-empty id',
    );
  }
  const want = stripFeatureExt(toPosix(id.trim())).toLowerCase();
  const files = listFeatureFiles([featureRoot], opts);
  const matched = files.filter((file) => {
    const rel = relFromRoot(featureRoot, file);
    const relStem = stripFeatureExt(rel).toLowerCase();
    const baseStem = stripFeatureExt(path.basename(rel)).toLowerCase();
    return relStem === want || baseStem === want;
  });
  if (matched.length === 0) {
    throw new Error(
      `[resolve-selection] no .feature file matched feature id "${id}" under ${featureRoot}`,
    );
  }
  if (matched.length > 1) {
    throw new Error(
      `[resolve-selection] feature id "${id}" is ambiguous; matched ${matched.length} files: ${matched
        .map((f) => relFromRoot(featureRoot, f))
        .join(', ')}. Qualify with a featureRoot-relative path.`,
    );
  }
  const all = scanBddScenarios({ featureRoots: [featureRoot], ...opts });
  const scenarios = sortScenarios(all.filter((s) => s.file === matched[0]));
  return {
    kind: 'feature',
    featureRoot,
    files: matched,
    scenarios,
  };
}

function resolveTag(featureRoot, selector, opts) {
  const predicate = parseTagExpression(selector.expression);
  const all = scanBddScenarios({ featureRoots: [featureRoot], ...opts });
  const scenarios = sortScenarios(all.filter((s) => predicate(tagSetOf(s))));
  const files = Array.from(new Set(scenarios.map((s) => s.file))).sort();
  return {
    kind: 'tag',
    featureRoot,
    files,
    scenarios,
  };
}

function resolveDomain(featureRoot, selector, opts) {
  const name = selector.name;
  if (typeof name !== 'string' || name.trim().length === 0) {
    throw new Error(
      '[resolve-selection] domain selector requires a non-empty name',
    );
  }
  // Normalise to a trailing-slash POSIX prefix so "billing" matches
  // "billing/checkout.feature" but not "billing-archive/x.feature".
  const prefix = `${toPosix(name.trim()).replace(/\/+$/, '')}/`;
  const all = scanBddScenarios({ featureRoots: [featureRoot], ...opts });
  const scenarios = sortScenarios(
    all.filter((s) => relFromRoot(featureRoot, s.file).startsWith(prefix)),
  );
  if (scenarios.length === 0) {
    throw new Error(
      `[resolve-selection] no scenarios found under domain "${name}" in ${featureRoot}`,
    );
  }
  const files = Array.from(new Set(scenarios.map((s) => s.file))).sort();
  return {
    kind: 'domain',
    featureRoot,
    files,
    scenarios,
  };
}

/**
 * lib/test-isolate/cli-options.js — argv → options for the `test-isolate` CLI.
 *
 * Story #5316: this lived inside `.agents/scripts/test-isolate.js`, a file no
 * test imports, so it scored the CRAP formula's untested maximum (210 at
 * cyclomatic 14 and 0% coverage) and carried the tree's `test-isolate.js`
 * cyclomatic breach row. It sits here beside `list-files.js`, `parse-tap.js`
 * and `runner.js` for the same reason they do: the CLI shell is unreachable
 * from a test, and everything reachable belongs under `lib/`.
 *
 * The long `else if` ladder it replaces was cyclomatic 14, above the repo's
 * must-fix ceiling of 12. Dispatching through two flag tables is the same
 * parse — same precedence, same tolerance for a value-taking flag that ends
 * the argv — at roughly half the branch count.
 */

/**
 * Flags that consume the following argv entry as a number, keyed by the
 * option each one sets.
 */
const NUMERIC_FLAGS = {
  '--workers': 'workers',
  '--max-bisect-depth': 'maxBisectDepth',
  '--max-bisect-targets': 'maxBisectTargets',
  '--suite-concurrency': 'suiteConcurrency',
};

/** Flags that are their own value. */
const BOOLEAN_FLAGS = {
  '--json': 'json',
  '--quiet': 'quiet',
};

/**
 * Defaults every parse starts from. Deliberately module-private: nothing in
 * production reads it, and exporting it so a test could assert against it
 * would both make that test tautological and land a test-only export on the
 * `dead-exports:production` ratchet.
 */
function defaultOptions() {
  return {
    pattern: undefined,
    workers: undefined,
    maxBisectDepth: 8,
    maxBisectTargets: 5,
    suiteConcurrency: 8,
    json: false,
    quiet: false,
  };
}

/**
 * Parse the `test-isolate` CLI's argv.
 *
 * Precedence, unchanged from the ladder this replaces:
 *   - a known numeric flag consumes the next entry, but only when there IS a
 *     next entry — a trailing `--workers` is ignored rather than setting NaN;
 *   - a known boolean flag sets its option;
 *   - the FIRST non-flag argument becomes the pattern, and later ones are
 *     ignored;
 *   - anything else is ignored, so an unknown `--flag` is never mistaken for
 *     the pattern.
 *
 * @param {string[]} [argv]
 * @returns {{
 *   pattern: string|undefined,
 *   workers: number|undefined,
 *   maxBisectDepth: number,
 *   maxBisectTargets: number,
 *   suiteConcurrency: number,
 *   json: boolean,
 *   quiet: boolean,
 * }}
 */
export function parseIsolateArgv(argv = []) {
  const options = defaultOptions();
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    const numericKey = NUMERIC_FLAGS[arg];
    if (numericKey && argv[i + 1]) {
      options[numericKey] = Number(argv[i + 1]);
      i += 1;
      continue;
    }
    const booleanKey = BOOLEAN_FLAGS[arg];
    if (booleanKey) {
      options[booleanKey] = true;
      continue;
    }
    if (!arg.startsWith('--') && !options.pattern) options.pattern = arg;
  }
  return options;
}

/**
 * workspace-provisioner.js
 *
 * Central authority for populating a fresh worktree (or remote-runner checkout)
 * with gitignored workspace files — by default `.env`, `.mcp.json`, and the
 * operator's local-override files (`.agentrc.local.json`,
 * `.agents/instructions.local.md`) — plus any other files declared in
 * `.agentrc.json orchestration.workspaceFiles`. The local-override files are
 * provisioned so a worktree-isolated agent honors the §1.E local-override
 * contract (e.g. `github.operatorHandle`) rather than silently falling back to
 * the committed `.agentrc.json` placeholders. Every caller that needs these
 * files in a non-main checkout should go through this module; ad-hoc copy
 * logic elsewhere in the codebase is a bug.
 *
 * Public API:
 *   - `provision({ sourceRoot, targetWorktree, files?, logger? })` — copies
 *     each listed file from source to target, skipping any that already exist
 *     at the target. Returns `{ copied, skipped, missing }`.
 *   - `verify({ worktree, files?, sourceRoot? })` — throws when a required
 *     file is missing. When `sourceRoot` is passed, the error carries a
 *     copy-ready remediation command the operator can run verbatim.
 *   - `resolveWorkspaceFiles(orchestrationConfig)` — resolves the list honoring
 *     the new `orchestration.workspaceFiles` key, the legacy
 *     `orchestration.worktreeIsolation.bootstrapFiles`, and the default.
 *   - `DEFAULT_WORKSPACE_FILES` — `['.env', '.mcp.json', '.agentrc.local.json',
 *     '.agents/instructions.local.md']`.
 */

import fs from 'node:fs';
import path from 'node:path';
import { NOOP_LOGGER } from './Logger.js';

// Keep in sync with `WORKTREE_ISOLATION_DEFAULTS.bootstrapFiles` in
// `./config/worktree-isolation.js`. The local-override files are listed even
// though they are frequently absent — `provision()` skips missing sources and
// `verify()` callers filter to files present at the source first, so a missing
// override never fails a worktree create.
export const DEFAULT_WORKSPACE_FILES = [
  '.env',
  '.mcp.json',
  '.agentrc.local.json',
  '.agents/instructions.local.md',
];

/**
 * Resolve the list of workspace files to provision.
 *
 * Precedence: explicit `orchestration.workspaceFiles` → legacy
 * `orchestration.worktreeIsolation.bootstrapFiles` → `DEFAULT_WORKSPACE_FILES`.
 *
 * @param {object} [orchestrationConfig]
 * @returns {string[]}
 */
export function resolveWorkspaceFiles(orchestrationConfig) {
  const cfg = orchestrationConfig ?? {};
  if (Array.isArray(cfg.workspaceFiles)) return cfg.workspaceFiles.slice();
  // Legacy `worktreeIsolation.bootstrapFiles` fallback — surviving callers:
  // tests/lib/workspace-provisioner.test.js, tests/lib/worktree/bootstrapper.test.js,
  // and consumer projects' `.agentrc.json` (config-schema still accepts it).
  const legacy = cfg.worktreeIsolation?.bootstrapFiles;
  if (Array.isArray(legacy)) return legacy.slice();
  return DEFAULT_WORKSPACE_FILES.slice();
}

/**
 * Validate a workspace-file name — must be relative, no `..`, no NULs, no
 * absolute paths.
 *
 * @param {string} name
 * @returns {string|null}  null on success, reason string on failure.
 */
function invalidNameReason(name) {
  if (typeof name !== 'string' || name.length === 0) return 'empty';
  const rel = path.normalize(name);
  if (rel.startsWith('..') || path.isAbsolute(rel) || rel.includes('\0')) {
    return 'traversal-or-absolute';
  }
  return null;
}

/**
 * Copy configured workspace files from `sourceRoot` into `targetWorktree`.
 * Existing target files are preserved (never overwritten). Missing sources are
 * silently skipped and reported in the `missing` array.
 *
 * @param {object} opts
 * @param {string} opts.sourceRoot     Absolute path to the main repo.
 * @param {string} opts.targetWorktree Absolute path to the target worktree.
 * @param {string[]} [opts.files]      File list; defaults to DEFAULT_WORKSPACE_FILES.
 * @param {object} [opts.logger]       `{ info, warn, error }`.
 * @returns {{ copied: string[], skipped: string[], missing: string[] }}
 */
export function provision({
  sourceRoot,
  targetWorktree,
  files = DEFAULT_WORKSPACE_FILES,
  logger = NOOP_LOGGER,
}) {
  if (!sourceRoot || typeof sourceRoot !== 'string') {
    throw new Error('workspace-provisioner: sourceRoot is required');
  }
  if (!targetWorktree || typeof targetWorktree !== 'string') {
    throw new Error('workspace-provisioner: targetWorktree is required');
  }

  const result = { copied: [], skipped: [], missing: [] };
  if (!Array.isArray(files) || files.length === 0) return result;

  for (const name of files) {
    const reason = invalidNameReason(name);
    if (reason) {
      logger.warn(
        `workspace-provisioner: skipped invalid name='${name}' (${reason})`,
      );
      continue;
    }
    const rel = path.normalize(name);
    const src = path.join(sourceRoot, rel);
    if (!fs.existsSync(src)) {
      result.missing.push(rel);
      continue;
    }
    const dst = path.join(targetWorktree, rel);
    if (fs.existsSync(dst)) {
      logger.info(
        `workspace-provisioner: skipped path=${dst} (already exists)`,
      );
      result.skipped.push(rel);
      continue;
    }
    try {
      fs.mkdirSync(path.dirname(dst), { recursive: true });
      fs.copyFileSync(src, dst);
      logger.info(`workspace-provisioner: copied source=${src} target=${dst}`);
      result.copied.push(rel);
    } catch (err) {
      logger.warn(
        `workspace-provisioner: copy failed name=${name}: ${err.message}`,
      );
    }
  }
  return result;
}

/**
 * Throw if any required workspace file is missing from `worktree`. Used as a
 * runtime guard (called right after every worktree create in
 * `single-story-init.js`) and as a test oracle.
 *
 * When `sourceRoot` is supplied, the thrown error carries the missing target
 * path and an exact `cp`/`copy` command the operator can paste to remediate.
 *
 * @param {object} opts
 * @param {string} opts.worktree
 * @param {string[]} [opts.files]
 * @param {string} [opts.sourceRoot] Main repo path; enables remediation hint.
 */
export function verify({
  worktree,
  files = DEFAULT_WORKSPACE_FILES,
  sourceRoot,
}) {
  if (!worktree || typeof worktree !== 'string') {
    throw new Error('workspace-provisioner: worktree is required');
  }
  const missing = [];
  for (const name of files) {
    if (invalidNameReason(name)) continue;
    const rel = path.normalize(name);
    const abs = path.join(worktree, rel);
    if (!fs.existsSync(abs)) missing.push({ name, rel, abs });
  }
  if (missing.length === 0) return;

  const namesList = missing.map((m) => m.name).join(', ');
  const pathsList = missing.map((m) => m.abs).join(', ');
  const lines = [
    `workspace-provisioner: required workspace file(s) missing from ${worktree}: ${namesList}`,
    `  missing path(s): ${pathsList}`,
  ];
  if (sourceRoot && typeof sourceRoot === 'string') {
    const copyCmd = process.platform === 'win32' ? 'copy /Y' : 'cp';
    for (const m of missing) {
      const src = path.join(sourceRoot, m.rel);
      lines.push(`  remediation: ${copyCmd} "${src}" "${m.abs}"`);
    }
  }
  throw new Error(lines.join('\n'));
}

/**
 * GitHub Provider — composition root (thin composer).
 *
 * Story #2462 (Epic #2453) split this class into nine sibling modules under
 * `./github/`. This file now does two things only:
 *
 *   1. **Holds the constructor** that captures config + opts + the gh-exec
 *      facade, then delegates gateway wiring to `composeGateways()` in
 *      `./github/compose.js`.
 *   2. **Installs the ITicketingProvider surface** as one-line delegating
 *      methods sourced from the `DELEGATIONS` table below — every public
 *      method forwards verbatim to a concrete gateway.
 *
 * Re-exports: only the five error-classification helpers still used by tests
 * that import through this barrel (classifyGithubError et al.). All other
 * symbols (mappers, auth helpers, sub-issue constants) are dead exports per
 * baselines/dead-exports.json and were removed in Story #3650 (Epic #3599).
 * Callers should import those symbols directly from their ./github/<sub>.js
 * module.
 *
 * Gateway map: tickets, sub-issues, comments, labels, branch-protection,
 * merge-methods, project-board, issues (epics + sub-tickets + branch probe
 * + raw GraphQL). Story #5008 retired the `prs` gateway — `single-story-close`
 * drives `gh pr create` directly — along with the sub-issue write surface and
 * the repo-wide recent-comments feed.
 */

import { createGh, gh as defaultGh } from '../lib/gh-exec.js';
import { ITicketingProvider } from '../lib/ITicketingProvider.js';
import { resolveToken } from './github/auth.js';
import { createInlineTicketCache } from './github/cache.js';
import { composeGateways } from './github/compose.js';
import {
  classifyGithubError,
  extractErrorFields,
  isPermissionSignal,
  isTransientByCodeOrMessage,
  isTransientStatus,
} from './github/errors.js';
import * as projects from './github/projects-v2-graphql.js';

export {
  classifyGithubError,
  extractErrorFields,
  isPermissionSignal,
  isTransientByCodeOrMessage,
  isTransientStatus,
};

export class GitHubProvider extends ITicketingProvider {
  constructor(config, opts = {}) {
    super();
    this.owner = config.owner;
    this.repo = config.repo;
    this.projectNumber = config.projectNumber ?? null;
    this.projectOwner = config.projectOwner ?? config.owner;
    this.projectName = config.projectName ?? null;
    this.operatorHandle = config.operatorHandle ?? null;
    this._explicitToken = opts.token ?? null;
    this._memoizedToken = opts.token ?? null;
    // Resolve the gh-exec default timeout (Story #2860). When the operator
    // sets `github.defaultTimeoutMs` in `.agentrc.json`, every `gh`
    // subprocess this provider spawns inherits that timeout ceiling. An
    // injected `opts.gh` is honored as-is so tests can drive the facade
    // without going through this fallback. Unset → 60_000 ms in code.
    if (opts.gh) {
      this._gh = opts.gh;
    } else {
      const defaultTimeoutMs = config.defaultTimeoutMs ?? 60_000;
      this._gh =
        defaultTimeoutMs > 0
          ? createGh(undefined, { timeoutMs: defaultTimeoutMs })
          : defaultGh;
    }
    this._cache = createInlineTicketCache();
    composeGateways(this);
  }

  get token() {
    if (this._memoizedToken) return this._memoizedToken;
    this._memoizedToken = resolveToken();
    return this._memoizedToken;
  }

  /**
   * The identifiers a native dependency-edge writer needs, handed over as an
   * explicit interface (Story #4544).
   *
   * `providers/github/blocked-by-add.js` talks to the dependencies REST API
   * directly, so it needs the `gh` facade plus `owner`/`repo` — none of which
   * the `ITicketingProvider` surface exposes. Its caller lives in the
   * orchestration layer (`plan-persist/story-ops.js`), and the alternative was
   * for that caller to reach through `provider._gh` — a private-by-convention
   * field — from outside this module. Naming the hand-off here keeps the
   * coupling declared and greppable instead of incidental: the provider
   * decides what it lends out, and the field stays private.
   *
   * @returns {{ gh: object, owner: string, repo: string }}
   */
  getDependencyWriteContext() {
    return { gh: this._gh, owner: this.owner, repo: this.repo };
  }

  static isInsufficientScopes(err) {
    return projects.isInsufficientScopes(err);
  }
}

/**
 * Delegation table. Each `[publicMethod, 'gatewayName.gatewayMethod']` pair
 * installs an async wrapper on `GitHubProvider.prototype` that forwards
 * every argument to the matching gateway method. This keeps the parity
 * surface explicit and the file under the thin-composer LOC ceiling.
 */
const DELEGATIONS = [
  ['graphql', 'issues.ghGraphql'],
  ['searchIssues', 'issues.searchIssues'],
  ['listIssuesByLabel', 'issues.listIssuesByLabel'],
  ['listTicketsByLabel', 'issues.listTicketsByLabel'],
  ['getParentIssue', 'issues.getParentIssue'],
  ['getEpic', 'issues.getEpic'],
  ['branchExists', 'issues.branchExists'],
  ['getSubTickets', 'issues.getSubTickets'],
  ['_getReferencedChildren', 'issues._getReferencedChildren'],
  ['getTickets', 'tickets.getTickets'],
  ['getTicket', 'tickets.getTicket'],
  ['getTicketDependencies', 'tickets.getTicketDependencies'],
  ['createIssue', 'tickets.createIssue'],
  ['updateTicket', 'tickets.updateTicket'],
  ['_applyLabelMutations', 'tickets._applyLabelMutations'],
  ['getNativeSubIssues', 'subIssues.getNativeSubIssues'],
  // The private alias predates the declared `getNativeSubIssues` port above
  // and still has call sites; both forward to the same gateway method, so the
  // two can never answer differently while the older name is retired.
  ['_getNativeSubIssues', 'subIssues.getNativeSubIssues'],
  ['getTicketComments', 'comments.getTicketComments'],
  ['deleteComment', 'comments.deleteComment'],
  ['postComment', 'comments.postComment'],
  ['getBranchProtection', 'branchProtection.getBranchProtection'],
  ['setBranchProtection', 'branchProtection.setBranchProtection'],
  ['ensureLabels', 'labels.ensureLabels'],
  ['listLabels', 'labels.listLabels'],
  ['deleteLabel', 'labels.deleteLabel'],
  ['_reconcileLabelsPresence', 'labels._reconcileLabelsPresence'],
  ['getMergeMethods', 'mergeMethods.getMergeMethods'],
  ['setMergeMethods', 'mergeMethods.setMergeMethods'],
  ['resolveOrCreateProject', 'projectBoard.resolveOrCreateProject'],
  ['ensureStatusField', 'projectBoard.ensureStatusField'],
  ['ensureProjectFields', 'projectBoard.ensureProjectFields'],
];
for (const [name, target] of DELEGATIONS) {
  const [gw, method] = target.split('.');
  GitHubProvider.prototype[name] = async function (...args) {
    return this[gw][method](...args);
  };
}

// Synchronous (void-returning or non-promise) delegations.
GitHubProvider.prototype.primeTicketCache = function (t) {
  this.tickets.primeTicketCache(t);
};
GitHubProvider.prototype.invalidateTicket = function (id) {
  this.tickets.invalidateTicket(id);
};
GitHubProvider.prototype._normalizeLabelListResult = function (r) {
  return this.labels._normalizeLabelListResult(r);
};
GitHubProvider.prototype._getChecklistChildren = function (body) {
  return this.issues._getChecklistChildren(body);
};
GitHubProvider.prototype._updateLabels = function (id, mutations, hasOther) {
  return this._applyLabelMutations(id, mutations, hasOther);
};

#!/usr/bin/env node
/**
 * .agents/scripts/quality-preview.js — Per-file MI/CRAP delta preview.
 *
 * Runs the maintainability + CRAP gates in-process via the per-kind
 * preview runners under `lib/baselines/preview-gates.js`, then merges
 * their structured envelopes into a single per-file delta table
 * contributors can read while the diff is still warm. Designed for
 * three callers:
 *
 *   1. `npm run quality:preview`   — interactive operator, pretty table.
 *   2. `npm run quality:watch`     — chokidar wrapper re-emits on save.
 *   3. `.husky/pre-commit`         — block the commit on threshold violations.
 *
 * The pre-commit hook passes `--staged` and nothing else — the index is
 * already the exact delta the operator is about to commit, and
 * `tests/pre-commit-hook.test.js` pins that `--changed-since` stays off it.
 * (This docblock previously claimed the hook passed `--changed-since HEAD`,
 * describing a wiring the hook has not used for some time; the stale prose
 * sent at least one bug report at the wrong flag — Story #5131.)
 *
 * `--staged` is merge-aware: while a merge is in progress the index is read
 * against `MERGE_HEAD` rather than `HEAD`, so a base-sync merge commit is
 * scored for the merging branch's own work and its conflict resolutions, not
 * for everything the base branch landed. See `resolveMergeHead` in
 * `lib/changed-files.js`.
 *
 * The CLI exits 0 when both envelopes report zero violations and the script
 * could not surface a regression. Any violation in either envelope, or any
 * non-zero gate exit, propagates as a non-zero exit code so git/husky/CI
 * surface the failure. The merge logic is exported as `mergeEnvelopes` for
 * unit testing without spawning the gate scripts.
 */

import path from 'node:path';
import process from 'node:process';
import {
  runCrapPreview,
  runMaintainabilityPreview,
} from './lib/baselines/preview-gates.js';
import { resolveMergeHead } from './lib/changed-files.js';
import { respondToHelp } from './lib/cli-usage.js';
import { getQuality, resolveConfig } from './lib/config-resolver.js';
import { resolveCyclomaticPolicy } from './lib/cyclomatic-ceiling.js';

const USAGE = {
  invocation:
    'node .agents/scripts/quality-preview.js [--staged | --changed-since <ref>] [--json]',
  summary:
    'Preview the per-file maintainability and CRAP deltas for the change set, and exit non-zero on any threshold violation.',
  flags: [
    [
      '--staged',
      'Score the git index only (the pre-commit-hook scope). During a merge the index is read against MERGE_HEAD.',
    ],
    [
      '--changed-since <ref>',
      'Score the diff against <ref> (default: HEAD). Last occurrence wins.',
    ],
    ['--json', 'Emit both gate envelopes plus the merged table as JSON.'],
  ],
};

/**
 * Framework default for `delivery.quality.codingGuardrails.cyclomaticFlag`,
 * used only when a caller drives `mergeEnvelopes` / `renderTable` without a
 * resolved config in hand (tests, and the pure-function surface). `runCli`
 * always passes the resolved value.
 */
const DEFAULT_CYCLOMATIC_FLAG = 8;

/**
 * Parse `--changed-since <ref>` from argv. Defaults to `HEAD` when the flag is
 * present without a value. Returns `null` when the flag is absent so callers
 * can fall through to the gate scripts' own diff defaults.
 *
 * **Last occurrence wins** (Story #4603). `npm run <alias> -- --changed-since <base>`
 * appends the operator's flag *after* any flag baked into the npm script, so a
 * first-wins scan silently discarded the operator's base and compared against
 * the script's hardcoded one instead — reporting a false green for a branch the
 * gate had never actually scored. Last-wins matches the convention every
 * mainstream CLI parser follows for repeated scalar flags, and makes the
 * npm-alias passthrough behave the way its callers already assume.
 *
 * @param {string[]} argv
 * @returns {string | null}
 */
export function parseChangedSinceArg(argv) {
  let resolved = null;
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] !== '--changed-since') continue;
    const next = argv[i + 1];
    resolved = next && !next.startsWith('--') ? next : 'HEAD';
  }
  return resolved;
}

/**
 * Detect `--json` (machine-readable mode). When set, the merged envelope is
 * written to stdout as JSON instead of the human-readable table; the exit code
 * still reflects gate health so CI runners can fail fast.
 *
 * @param {string[]} argv
 * @returns {boolean}
 */
export function parseJsonFlag(argv) {
  return argv.includes('--json');
}

/**
 * Detect `--staged` (pre-commit mode). Used by `.husky/pre-commit` to
 * scope both MI and CRAP preview gates to `git diff --name-only --cached`
 * so only index (staged) paths are scored. When present, `--staged` takes
 * precedence over `--changed-since`.
 *
 * @param {string[]} argv
 * @returns {boolean}
 */
export function parseStagedFlag(argv) {
  return argv.includes('--staged');
}

/**
 * Coerce a caller-supplied flag ceiling to a usable number, falling back to
 * the framework default for anything non-finite.
 *
 * @param {unknown} value
 * @returns {number}
 */
function normalizeFlag(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : DEFAULT_CYCLOMATIC_FLAG;
}

/**
 * Fold one CRAP violation into its per-file aggregate row. Mutates `row`.
 *
 * Split out of `mergeEnvelopes` (Story #4923): threading the resolved
 * `cyclomaticFlag` through pushed that function from c=12 — exactly at the
 * must-fix ceiling — to c=13, and the same Story starts *enforcing* that
 * ceiling. Recording its own breach in `baselines/cyclomatic.json` would have
 * been the first re-spend of the slack the Story reclaims.
 *
 * @param {{ worstCrapDelta: number, newOverCeilingMethods: number }} row
 * @param {{ crap?: number, ceiling?: number, baseline?: number, cyclomatic?: number, kind?: string }} v
 * @param {number} flag resolved `codingGuardrails.cyclomaticFlag`
 * @returns {void}
 */
function foldCrapViolation(row, v, flag) {
  const crap = Number(v.crap ?? 0);
  const isNew = v.kind === 'new';
  const against = Number((isNew ? v.ceiling : v.baseline) ?? 0);
  const delta = crap - against;
  if (Number.isFinite(delta) && delta > row.worstCrapDelta) {
    row.worstCrapDelta = delta;
  }
  if (!isNew) return;
  const cyclomatic = Number(v.cyclomatic ?? 0);
  if (Number.isFinite(cyclomatic) && cyclomatic > flag) {
    row.newOverCeilingMethods += 1;
  }
}

/**
 * Merge an MI envelope (from `runMaintainabilityPreview`) and a CRAP
 * envelope (from `runCrapPreview`) into a per-file delta map. Pure —
 * no I/O, no spawn. Tests pin the math without invoking the runners.
 *
 * Output rows are keyed by file (forward-slash relative path) and carry:
 *   - `miDrop`: maintainability score drop from baseline (0 when unchanged or
 *     improved). Higher = worse.
 *   - `worstCrapDelta`: largest CRAP regression delta among the file's
 *     methods (max of `crap - baseline` for matched-baseline rows, `crap`
 *     for new-method rows). 0 when the file has no CRAP violations.
 *   - `newOverCeilingMethods`: count of new-method violations (kind:'new')
 *     scoring above the flag ceiling. The CRAP envelope's `cyclomatic` field
 *     is the per-method `c` reading.
 *
 * `cyclomaticFlag` is the resolved
 * `delivery.quality.codingGuardrails.cyclomaticFlag` (Story #4923). It used to
 * be the literal `8` written into this function and into the column header, so
 * a consumer that tuned the knob saw its own value validated by the schema,
 * defaulted by the bootstrap, resolved by `lib/config/quality.js` — and then
 * ignored here. The parameter defaults to the framework default so a caller
 * with no config in hand still gets the historical reading.
 *
 * @param {{ violations?: Array<{ file: string, drop?: number }> } | null} miEnvelope
 * @param {{ violations?: Array<{
 *   file: string,
 *   crap: number,
 *   baseline: number | null,
 *   ceiling: number,
 *   cyclomatic: number,
 *   kind: 'new' | 'regression' | 'drifted-regression' | string,
 * }>} | null} crapEnvelope
 * @param {{ cyclomaticFlag?: number }} [opts]
 * @returns {{
 *   rows: Array<{
 *     file: string,
 *     miDrop: number,
 *     worstCrapDelta: number,
 *     newOverCeilingMethods: number,
 *   }>,
 *   totals: { miRegressions: number, crapViolations: number },
 *   cyclomaticFlag: number,
 * }}
 */
export function mergeEnvelopes(
  miEnvelope,
  crapEnvelope,
  { cyclomaticFlag = DEFAULT_CYCLOMATIC_FLAG } = {},
) {
  const flag = normalizeFlag(cyclomaticFlag);
  /** @type {Map<string, { miDrop: number, worstCrapDelta: number, newOverCeilingMethods: number }>} */
  const byFile = new Map();
  const ensure = (file) => {
    let row = byFile.get(file);
    if (!row) {
      row = { miDrop: 0, worstCrapDelta: 0, newOverCeilingMethods: 0 };
      byFile.set(file, row);
    }
    return row;
  };

  const miViolations = miEnvelope?.violations ?? [];
  for (const v of miViolations) {
    if (!v?.file) continue;
    const row = ensure(v.file);
    const drop = Number(v.drop ?? 0);
    if (Number.isFinite(drop) && drop > row.miDrop) row.miDrop = drop;
  }

  const crapViolations = crapEnvelope?.violations ?? [];
  for (const v of crapViolations) {
    if (!v?.file) continue;
    foldCrapViolation(ensure(v.file), v, flag);
  }

  const rows = Array.from(byFile.entries())
    .map(([file, agg]) => ({ file, ...agg }))
    .sort((a, b) => a.file.localeCompare(b.file));

  return {
    rows,
    totals: {
      miRegressions: miEnvelope?.summary?.regressions ?? 0,
      crapViolations:
        (crapEnvelope?.summary?.regressions ?? 0) +
        (crapEnvelope?.summary?.newViolations ?? 0),
    },
    cyclomaticFlag: flag,
    // Story #5313: advisories ride the merge but never the exit code.
    advisories: advisoriesOf(crapEnvelope),
  };
}

/**
 * The cyclomatic advisories a CRAP envelope carries (Story #5313), or none.
 *
 * @param {{ cyclomaticAdvisories?: unknown } | null | undefined} crapEnvelope
 * @returns {Array<{ file: string, method: string, startLine: number, cyclomatic: number }>}
 */
function advisoriesOf(crapEnvelope) {
  const list = crapEnvelope?.cyclomaticAdvisories;
  return Array.isArray(list) ? list : [];
}

/**
 * Print the advisories block when there is one (Story #5313). Split out of
 * `emitReport` so that function's branching stays inside its committed
 * cyclomatic budget.
 *
 * @param {Array<object>} advisories
 * @param {{ write: (s: string) => void }} stdout
 * @returns {void}
 */
function writeAdvisories(advisories, stdout) {
  const block = renderAdvisories(advisories);
  if (block) stdout.write(`\n${block}\n`);
}

/**
 * Render the cyclomatic advisories block (Story #5313), or `null` when the
 * scan carried none. One line per method at or over the ceiling; the block
 * says outright that it is advisory so a reader does not hunt for the exit
 * code it did not change.
 *
 * @param {Array<{ file: string, method: string, startLine: number, cyclomatic: number }>} advisories
 * @returns {string|null}
 */
export function renderAdvisories(advisories) {
  const list = Array.isArray(advisories) ? advisories : [];
  if (list.length === 0) return null;
  return [
    `Advisory — ${list.length} method(s) at cyclomatic 12 or above (reported, not a verdict; check-cyclomatic.js owns the ratchet):`,
    ...list.map(
      (a) => `  - ${a.file}:${a.startLine} ${a.method} (c=${a.cyclomatic})`,
    ),
  ].join('\n');
}

/**
 * Render the named diagnostics a gate envelope carries, or `null` when it
 * carries none (Story #4866).
 *
 * A diagnostic is what a gate emits *instead of* per-method verdicts when it
 * has established that no verdict it could produce would be meaningful — an
 * incomparable baseline, or a comparison basis whose drifted-row ratio proves
 * the two sides disagree on line coordinates. It must reach the operator
 * verbatim: the gate exits 0, so silence would read as a clean run.
 *
 * @param {Array<{ envelope: { diagnostics?: Array<{name: string, message: string}> } | null }>} results
 * @returns {string | null}
 */
export function renderDiagnostics(results) {
  const lines = [];
  for (const { envelope } of results ?? []) {
    for (const d of envelope?.diagnostics ?? []) {
      lines.push(`[${d.name}] ${d.message}`);
    }
  }
  return lines.length === 0 ? null : lines.join('\n');
}

/**
 * Compute the CLI exit code from a merge result + per-gate exit codes. Pure.
 *
 * The exit code is non-zero (1) whenever:
 *   - either gate returned a non-zero exit code (real violations or runtime
 *     failure), OR
 *   - the merged envelope reports any violation rows at all.
 *
 * Both signals are combined so a transient gate failure (e.g. JSON write
 * error) still surfaces even if the violations array happens to be empty.
 *
 * Advisories (`merged.advisories`, Story #5313) are deliberately not read
 * here: a method at cyclomatic 12 or above is reported and exits 0.
 *
 * @param {{ rows: Array<unknown>, totals: { miRegressions: number, crapViolations: number } }} merged
 * @param {number} miExit
 * @param {number} crapExit
 * @returns {number}
 */
export function computeExitCode(merged, miExit, crapExit) {
  if (miExit !== 0 || crapExit !== 0) return 1;
  if (merged.rows.length > 0) return 1;
  if (merged.totals.miRegressions > 0) return 1;
  if (merged.totals.crapViolations > 0) return 1;
  return 0;
}

/**
 * Render the per-file delta table. Columns:
 *   "file", "MI delta", "worst CRAP delta", "new-method count over c=<flag>".
 *
 * The last header used to hardcode `c=8`, which quietly lied to any consumer
 * that had tuned `codingGuardrails.cyclomaticFlag`. It now names the value the
 * count was actually taken against, read off the merge result — through the
 * same `normalizeFlag` the merge itself uses, rather than the second, hand-
 * inlined copy of that coercion this function used to carry.
 *
 * Pure — accepts pre-computed merge rows and returns a multi-line string. The
 * table renders even on a clean diff so operators see the "no drift" signal.
 *
 * @param {{ rows: Array<{ file: string, miDrop: number, worstCrapDelta: number, newOverCeilingMethods: number }>, totals: { miRegressions: number, crapViolations: number }, cyclomaticFlag?: number }} merged
 * @returns {string}
 */
/**
 * The table's body: one row per regressed file, or the single placeholder
 * line that keeps the "no drift" signal visible on a clean diff.
 *
 * Split out of `renderTable` so that function keeps a flat shape — the
 * empty-vs-populated branch and the row loop together carried it above the
 * per-method CRAP contract the pre-push preview enforces.
 *
 * @param {Array<{ file: string, miDrop: number, worstCrapDelta: number, newOverCeilingMethods: number }>} rows
 * @returns {string[]}
 */
function tableBodyLines(rows) {
  if (rows.length === 0) return ['| _(no per-file regressions)_ | — | — | — |'];
  return rows.map(
    (row) =>
      `| ${row.file} | -${row.miDrop.toFixed(2)} | +${row.worstCrapDelta.toFixed(2)} | ${row.newOverCeilingMethods} |`,
  );
}

export function renderTable(merged) {
  const flag = normalizeFlag(merged?.cyclomaticFlag);
  const header = [
    'file',
    'MI delta',
    'worst CRAP delta',
    `new-method count over c=${flag}`,
  ];
  return [
    `| ${header.join(' | ')} |`,
    `| ${header.map(() => '---').join(' | ')} |`,
    ...tableBodyLines(merged.rows),
    '',
    `Totals: MI regressions=${merged.totals.miRegressions} · CRAP violations=${merged.totals.crapViolations}`,
  ].join('\n');
}

/**
 * Resolve `codingGuardrails.cyclomaticFlag` for the tree at `cwd`
 * (Story #4923), falling back to the framework default when the config cannot
 * be resolved at all.
 *
 * Best-effort by design: `quality:preview` is a developer-facing report, and a
 * run in a tree with no readable `.agentrc.json` should still render its table
 * rather than abort. Extracted from `runCli` rather than inlined so the CLI
 * body stays under the cyclomatic must-fix ceiling this same Story starts
 * enforcing — a gate whose own delivery breaches it is not a gate.
 *
 * @param {{ cwd: string, stderr: { write: (s: string) => void } }} args
 * @returns {number}
 */
function resolveCyclomaticFlag({ cwd, stderr }) {
  try {
    return resolveCyclomaticPolicy(getQuality(resolveConfig({ cwd }))).flag;
  } catch (err) {
    stderr.write(
      `[quality:preview] config resolution failed, using cyclomaticFlag=${DEFAULT_CYCLOMATIC_FLAG}: ${err?.message ?? err}\n`,
    );
    return DEFAULT_CYCLOMATIC_FLAG;
  }
}

/**
 * Invoke one preview runner, degrading a thrown failure into the same
 * `{ exitCode: 1, envelope: null }` shape a real gate failure produces.
 *
 * Both runners degraded identically before, in two hand-copied `catch`
 * arms; folding them into one helper removes the copy and keeps `runCli` a
 * pipeline rather than a pair of inlined error handlers. The emitted message
 * is byte-identical to the arm it replaces — `label` supplies the `MI` /
 * `CRAP` prefix.
 *
 * @param {(args: object) => Promise<{exitCode: number, envelope: object|null}>} runner
 * @param {{cwd: string, staged: boolean, changedSinceRef: string|null}} args
 * @param {'MI'|'CRAP'} label
 * @param {{ write: (s: string) => void }} stderr
 * @returns {Promise<{exitCode: number, envelope: object|null}>}
 */
function runGateSafely(runner, args, label, stderr) {
  return runner(args).catch((err) => {
    stderr.write(
      `[quality:preview] ${label} runner failed: ${err?.message ?? err}\n`,
    );
    return { exitCode: 1, envelope: null };
  });
}

/**
 * Render the scope header line.
 *
 * Story #5131 — when `--staged` runs during a merge the scope is re-based to
 * `MERGE_HEAD`, and the header says so. Without that line the operator sees a
 * table whose row count does not match `git diff --cached` with no way to tell
 * the narrowing was deliberate.
 *
 * The merge state is resolved here rather than read back off a gate envelope's
 * `summary.diffRef`: that field means "the ref this scope was resolved
 * against" for every scope kind, so anything that populates it — a future
 * scope mode, a test stub — would render a merge banner over a repo that is
 * not merging. Resolving it after the `!staged` early return also keeps the
 * probe off the `--changed-since` path, which has no use for it.
 *
 * @param {{ staged: boolean, ref: string|null, cwd: string }} args
 * @returns {string}
 */
function stagedScopeLine({ staged, ref, cwd }) {
  if (!staged) return `scope=diff ref=${ref}\n\n`;
  const mergeHead = resolveMergeHead({ cwd });
  if (!mergeHead) return 'scope=staged (git diff --cached)\n\n';
  return (
    `scope=staged (git diff --cached ${mergeHead.slice(0, 12)}) — merge in ` +
    "progress: scored against MERGE_HEAD, not HEAD, so the base branch's " +
    'incoming files are excluded\n\n'
  );
}

/**
 * Write the run's report — the `--json` envelope, or the human-readable
 * table plus any gate diagnostics and the non-zero-exit summary.
 *
 * Split out of `runCli` (Story #5109): the rendering half carried five of
 * that function's decision points, which put it over the per-method CRAP
 * contract the pre-push preview enforces. Output bytes are unchanged in both
 * modes. The exit code stays with the caller — this function only reports.
 *
 * @param {{
 *   json: boolean,
 *   staged: boolean,
 *   ref: string|null,
 *   cwd: string,
 *   miResult: {exitCode: number, envelope: object|null},
 *   crapResult: {exitCode: number, envelope: object|null},
 *   merged: ReturnType<typeof mergeEnvelopes>,
 *   stdout: { write: (s: string) => void },
 *   stderr: { write: (s: string) => void },
 * }} args
 * @returns {void}
 */
function emitReport({
  json,
  staged,
  ref,
  cwd,
  miResult,
  crapResult,
  merged,
  stdout,
  stderr,
}) {
  const miExit = miResult.exitCode;
  const crapExit = crapResult.exitCode;
  if (json) {
    stdout.write(
      `${JSON.stringify(
        {
          ref: staged ? null : ref,
          staged,
          mi: { exit: miExit, envelope: miResult.envelope },
          crap: { exit: crapExit, envelope: crapResult.envelope },
          merged,
        },
        null,
        2,
      )}\n`,
    );
    return;
  }
  stdout.write('\n--- quality:preview ---\n');
  stdout.write(stagedScopeLine({ staged, ref, cwd }));
  stdout.write(`${renderTable(merged)}\n`);
  writeAdvisories(merged.advisories, stdout);
  const diagnostics = renderDiagnostics([miResult, crapResult]);
  if (diagnostics) stdout.write(`\n${diagnostics}\n`);
  if (miExit !== 0 || crapExit !== 0) {
    stderr.write(
      `\n[quality:preview] gate exits: mi=${miExit} crap=${crapExit}\n`,
    );
  }
}

/**
 * Top-level CLI entry: invoke both per-kind preview runners, merge, render,
 * and exit with the right code. Exposed as `runCli` so tests can drive the
 * full pipeline through injected runner stubs.
 *
 * @param {{
 *   argv?: string[],
 *   cwd?: string,
 *   stdout?: { write: (s: string) => void },
 *   stderr?: { write: (s: string) => void },
 *   runMi?: typeof runMaintainabilityPreview,
 *   runCrap?: typeof runCrapPreview,
 * }} [opts]
 * @returns {Promise<{ exitCode: number, merged: ReturnType<typeof mergeEnvelopes> }>}
 */
export async function runCli({
  argv = process.argv.slice(2),
  cwd = process.cwd(),
  stdout = process.stdout,
  stderr = process.stderr,
  runMi = runMaintainabilityPreview,
  runCrap = runCrapPreview,
} = {}) {
  const json = parseJsonFlag(argv);
  const staged = parseStagedFlag(argv);
  const ref = staged ? null : (parseChangedSinceArg(argv) ?? 'HEAD');

  // Story #5109 — the two gates run **one after the other**, not under a
  // `Promise.all`. Each scores its batch with its own `runOnPool` budget
  // sized to `os.availableParallelism()`, so overlapping them oversubscribed
  // the host by 2x and stacked two escomplex heaps: a 58-file preview peaked
  // at 1.0-1.2 GB RSS for 3.9 s of CPU. Serialising them bounds the preview
  // to one `availableParallelism` of workers and one heap at a time. The two
  // runners share no state and neither reads the other's envelope, so the
  // emitted envelopes — and therefore the merged table and the exit code —
  // are identical either way; only the peak cost differs.
  //
  // Each runner gets its own options literal rather than one shared object,
  // so serialising them cannot introduce a coupling the concurrent form
  // did not have.
  const miResult = await runGateSafely(
    runMi,
    { cwd, staged, changedSinceRef: ref },
    'MI',
    stderr,
  );
  const crapResult = await runGateSafely(
    runCrap,
    { cwd, staged, changedSinceRef: ref },
    'CRAP',
    stderr,
  );

  // Story #4923 — the over-ceiling column counts against the *resolved*
  // `codingGuardrails.cyclomaticFlag`, not the literal that used to be written
  // into `mergeEnvelopes` and the column header.
  const cyclomaticFlag = resolveCyclomaticFlag({ cwd, stderr });
  const merged = mergeEnvelopes(miResult.envelope, crapResult.envelope, {
    cyclomaticFlag,
  });

  emitReport({
    json,
    staged,
    ref,
    cwd,
    miResult,
    crapResult,
    merged,
    stdout,
    stderr,
  });

  return {
    exitCode: computeExitCode(merged, miResult.exitCode, crapResult.exitCode),
    merged,
  };
}

// cli-opt-out: Windows-aware main-guard with leading-slash drive-letter normalisation; mirrors quality-watch.js so the diagnostic surface stays consistent across the gate suite.
// Only run main when invoked directly — keep the module importable from tests.
const isDirect = (() => {
  try {
    const invoked = process.argv[1] ? path.resolve(process.argv[1]) : '';
    const self = new URL(import.meta.url).pathname;
    const normalizedSelf = /^\/[A-Za-z]:/.test(self) ? self.slice(1) : self;
    return path.resolve(normalizedSelf) === invoked;
  } catch {
    return false;
  }
})();

if (isDirect && !respondToHelp(process.argv.slice(2), USAGE)) {
  runCli().then(({ exitCode }) => {
    process.exit(exitCode);
  });
}

// lib/cli/__tests__/registry-agents-in-sync.test.js
/**
 * Unit tests for the `agents-in-sync` doctor check's config-driven gate
 * (Story #4530, M7-B) — specifically the `.agentrc.json` /
 * `.agentrc.local.json` reads that resolve `delivery.routing.
 * roleScopedAgents` without pulling in the AJV-backed `resolveConfig()`
 * chain (registry.js's own "Node built-ins only" contract).
 *
 * `tests/cli/registry.test.js` covers the check's ok/detail/remedy shape via
 * the direct `roleScopedAgents` override seam; this file covers the config
 * READ path itself — default (no config), base-only, local-override, and
 * malformed-config-degrades-to-default.
 */

import assert from 'node:assert/strict';
import path from 'node:path';
import { describe, it } from 'node:test';

import { registry } from '../registry.js';

const agentsInSync = registry.find((c) => c.name === 'agents-in-sync');

const ROOT = path.join(path.sep, 'consumer');
const SRC_DIR = path.join(ROOT, '.agents', 'agents');
const DEST_DIR = path.join(ROOT, '.claude', 'agents');
const AGENTRC = path.join(ROOT, '.agentrc.json');
const AGENTRC_LOCAL = path.join(ROOT, '.agentrc.local.json');

/** Minimal readFileSync-only fs fake keyed by absolute path. */
function makeFsFake(seed = {}) {
  const files = new Map(Object.entries(seed));
  return {
    readFileSync(p, _enc) {
      if (!files.has(p)) {
        const err = new Error(`ENOENT: no such file or directory, open '${p}'`);
        err.code = 'ENOENT';
        throw err;
      }
      return files.get(p);
    },
  };
}

/** One unmaterialized source, no dest — the branch that consults the flag. */
function readDirFixture() {
  return (dir) => {
    if (dir === SRC_DIR) return ['story-worker.md'];
    if (dir === DEST_DIR) return [];
    return [];
  };
}

describe('agents-in-sync — resolves roleScopedAgents from .agentrc.json (no AJV)', () => {
  it('defaults to fatal (true) when no .agentrc.json exists at all', () => {
    const result = agentsInSync.run({
      projectRoot: ROOT,
      fsImpl: makeFsFake({}),
      readDir: readDirFixture(),
    });
    assert.equal(result.ok, false);
  });

  it('reads roleScopedAgents:false from the base .agentrc.json', () => {
    const result = agentsInSync.run({
      projectRoot: ROOT,
      fsImpl: makeFsFake({
        [AGENTRC]: JSON.stringify({
          delivery: { routing: { roleScopedAgents: false } },
        }),
      }),
      readDir: readDirFixture(),
    });
    assert.equal(result.ok, true);
    assert.match(result.detail, /roleScopedAgents is disabled/);
  });

  it('reads roleScopedAgents:true explicitly from the base .agentrc.json', () => {
    const result = agentsInSync.run({
      projectRoot: ROOT,
      fsImpl: makeFsFake({
        [AGENTRC]: JSON.stringify({
          delivery: { routing: { roleScopedAgents: true } },
        }),
      }),
      readDir: readDirFixture(),
    });
    assert.equal(result.ok, false);
  });

  it('a local override WINS over the base value (local:false over base:true)', () => {
    const result = agentsInSync.run({
      projectRoot: ROOT,
      fsImpl: makeFsFake({
        [AGENTRC]: JSON.stringify({
          delivery: { routing: { roleScopedAgents: true } },
        }),
        [AGENTRC_LOCAL]: JSON.stringify({
          delivery: { routing: { roleScopedAgents: false } },
        }),
      }),
      readDir: readDirFixture(),
    });
    assert.equal(
      result.ok,
      true,
      'local override must win over the base value',
    );
  });

  it('a local override WINS the other direction too (local:true over base:false)', () => {
    const result = agentsInSync.run({
      projectRoot: ROOT,
      fsImpl: makeFsFake({
        [AGENTRC]: JSON.stringify({
          delivery: { routing: { roleScopedAgents: false } },
        }),
        [AGENTRC_LOCAL]: JSON.stringify({
          delivery: { routing: { roleScopedAgents: true } },
        }),
      }),
      readDir: readDirFixture(),
    });
    assert.equal(result.ok, false);
  });

  it('degrades to the true default when .agentrc.json is malformed JSON, rather than throwing', () => {
    assert.doesNotThrow(() => {
      const result = agentsInSync.run({
        projectRoot: ROOT,
        fsImpl: makeFsFake({ [AGENTRC]: '{not valid json' }),
        readDir: readDirFixture(),
      });
      assert.equal(
        result.ok,
        false,
        'malformed config degrades to the true default',
      );
    });
  });

  it('an explicit roleScopedAgents opt bypasses the config reads entirely', () => {
    const fsFake = makeFsFake({
      [AGENTRC]: JSON.stringify({
        delivery: { routing: { roleScopedAgents: true } },
      }),
    });
    const result = agentsInSync.run({
      projectRoot: ROOT,
      fsImpl: fsFake,
      roleScopedAgents: false, // overrides the base:true config
      readDir: readDirFixture(),
    });
    assert.equal(result.ok, true, 'explicit override must win over config');
  });
});

// lib/migrations/__tests__/index.test.js
/**
 * Unit tests for lib/migrations/index.js — the version-keyed migration runner.
 *
 * All tests drive runMigrations through injected seams (a `log` capture and a
 * fixture `registry`) over an in-memory plain-object context, so no real
 * stdout write and no real filesystem I/O occur (testing-standards § Unit).
 *
 * Coverage contract (Story #3501 AC):
 *   - Module shape: runMigrations named export + ordered `migrations` registry
 *     array (which ships empty).
 *   - Version filtering: only steps with fromVersion < version <= toVersion
 *     apply, in ascending version order.
 *   - Idempotency: a second pass over the same context applies nothing
 *     (detect() returns false post-apply).
 *   - Log seam: each applied step prints `migrated <version>: <description>`.
 */

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import runMigrations, { compareVersions, migrations } from '../index.js';

// ---------------------------------------------------------------------------
// Fixture steps
// ---------------------------------------------------------------------------

/**
 * Build a fixture step keyed on a context flag. `detect` returns true only
 * while the flag is unset; `apply` sets it. This satisfies the idempotency
 * contract: once applied, detect returns false.
 *
 * @param {string} version
 * @param {string} flag - ctx property the step toggles.
 * @returns {{ version: string, description: string, detect: Function, apply: Function }}
 */
function makeStep(version, flag) {
  return {
    version,
    description: `set ${flag}`,
    detect: (ctx) => ctx[flag] !== true,
    apply: (ctx) => {
      ctx[flag] = true;
    },
  };
}

/** A deliberately out-of-order registry to prove the runner sorts ascending. */
function fixtureRegistry() {
  return [
    makeStep('1.4.0', 'a140'),
    makeStep('1.2.0', 'a120'),
    makeStep('1.3.0', 'a130'),
    makeStep('1.5.0', 'a150'),
  ];
}

// ---------------------------------------------------------------------------
// Module shape
// ---------------------------------------------------------------------------

describe('migrations module exports', () => {
  it('exports runMigrations as the default function', () => {
    assert.equal(typeof runMigrations, 'function');
  });

  it('exports an ordered `migrations` registry array', () => {
    assert.ok(Array.isArray(migrations));
  });

  // Story #4531 added the mi-drop-knobs retirement; Story #4545 appended the
  // verify-concurrency-cap retirement (both 2.1.0); Story #4604 appended the
  // epic-AC-tag retirement at 2.2.0; the Story #4722 follow-up appended the
  // maxSeedWords retirement at 2.11.0; Story #4811 appended the
  // codebaseSnapshot retirement at 2.20.0; the Story #5004 follow-up appended
  // the lintBaseline-command retirement at 2.32.0; Story #5312 appended the
  // planning-limit-knob retirement at 2.57.0; Story #5313 appended the
  // delivery-limit-knob retirement at the same version. The registry's
  // declaration order is what fixes the run order within a version — pin it.
  it('ships the real steps in ascending version + declaration order', () => {
    assert.equal(migrations.length, 8);
    assert.deepEqual(
      migrations.map((s) => s.version),
      [
        '2.1.0',
        '2.1.0',
        '2.2.0',
        '2.11.0',
        '2.20.0',
        '2.32.0',
        '2.57.0',
        '2.57.0',
      ],
    );
    assert.match(migrations[0].description, /mi|maintainability/i);
    assert.match(migrations[1].description, /concurrency/i);
    assert.match(migrations[2].description, /epic-<id>-ac-N/);
    assert.match(migrations[3].description, /maxSeedWords/);
    assert.match(migrations[4].description, /codebaseSnapshot/);
    assert.match(migrations[5].description, /lintBaseline/);
    assert.match(migrations[6].description, /complexityGate/);
    assert.match(migrations[7].description, /freshCriticSampleRate/);
  });
});

// ---------------------------------------------------------------------------
// compareVersions
// ---------------------------------------------------------------------------

describe('compareVersions', () => {
  it('orders by major, then minor, then patch', () => {
    assert.ok(compareVersions('1.2.0', '1.3.0') < 0);
    assert.ok(compareVersions('2.0.0', '1.9.9') > 0);
    assert.equal(compareVersions('1.4.0', '1.4.0'), 0);
    assert.ok(compareVersions('1.4.1', '1.4.0') > 0);
  });
});

// ---------------------------------------------------------------------------
// AC — version filtering + ascending order
// ---------------------------------------------------------------------------

describe('runMigrations — version filtering and ordering', () => {
  it('applies only steps with fromVersion < version <= toVersion, ascending', () => {
    const ctx = {};
    const order = [];
    const log = (msg) => order.push(msg);

    const result = runMigrations({
      fromVersion: '1.2.0',
      toVersion: '1.4.0',
      ctx,
      log,
      registry: fixtureRegistry(),
    });

    // 1.2.0 == fromVersion → excluded (already in the tree).
    // 1.5.0 > toVersion → excluded.
    // 1.3.0 and 1.4.0 apply, in ascending order.
    assert.deepEqual(result.applied, ['1.3.0', '1.4.0']);
    assert.deepEqual(order, [
      'migrated 1.3.0: set a130',
      'migrated 1.4.0: set a140',
    ]);
    assert.equal(ctx.a120, undefined);
    assert.equal(ctx.a130, true);
    assert.equal(ctx.a140, true);
    assert.equal(ctx.a150, undefined);
  });

  it('includes the step at exactly toVersion (inclusive upper bound)', () => {
    const ctx = {};
    const result = runMigrations({
      fromVersion: '1.2.0',
      toVersion: '1.5.0',
      ctx,
      log: () => {},
      registry: fixtureRegistry(),
    });
    assert.deepEqual(result.applied, ['1.3.0', '1.4.0', '1.5.0']);
  });

  it('excludes the step at exactly fromVersion (exclusive lower bound)', () => {
    const ctx = {};
    const result = runMigrations({
      fromVersion: '1.3.0',
      toVersion: '1.5.0',
      ctx,
      log: () => {},
      registry: fixtureRegistry(),
    });
    assert.deepEqual(result.applied, ['1.4.0', '1.5.0']);
    // 1.2.0 and 1.3.0 never ran.
    assert.equal(ctx.a120, undefined);
    assert.equal(ctx.a130, undefined);
  });

  it('applies nothing when the range is empty', () => {
    const ctx = {};
    const result = runMigrations({
      fromVersion: '1.5.0',
      toVersion: '1.5.0',
      ctx,
      log: () => {},
      registry: fixtureRegistry(),
    });
    assert.deepEqual(result.applied, []);
  });
});

// ---------------------------------------------------------------------------
// AC — idempotency
// ---------------------------------------------------------------------------

describe('runMigrations — idempotency', () => {
  it('applies nothing on a second pass over the same context', () => {
    const ctx = {};
    const registry = fixtureRegistry();
    const range = { fromVersion: '1.2.0', toVersion: '1.5.0', ctx, registry };

    const first = runMigrations({ ...range, log: () => {} });
    assert.deepEqual(first.applied, ['1.3.0', '1.4.0', '1.5.0']);

    const secondLog = [];
    const second = runMigrations({
      ...range,
      log: (msg) => secondLog.push(msg),
    });

    // Second pass: every in-range step is skipped because detect() now
    // returns false post-apply.
    assert.deepEqual(second.applied, []);
    assert.deepEqual(second.skipped, ['1.3.0', '1.4.0', '1.5.0']);
    assert.equal(secondLog.length, 0);
  });
});

// ---------------------------------------------------------------------------
// AC — log seam
// ---------------------------------------------------------------------------

describe('runMigrations — log seam', () => {
  it('prints `migrated <version>: <description>` for each applied step', () => {
    const lines = [];
    runMigrations({
      fromVersion: '1.0.0',
      toVersion: '1.3.0',
      ctx: {},
      log: (msg) => lines.push(msg),
      registry: [makeStep('1.3.0', 'a130')],
    });
    assert.deepEqual(lines, ['migrated 1.3.0: set a130']);
  });

  it('does not log a step that detect skips', () => {
    const lines = [];
    runMigrations({
      fromVersion: '1.0.0',
      toVersion: '1.3.0',
      ctx: { a130: true }, // already applied
      log: (msg) => lines.push(msg),
      registry: [makeStep('1.3.0', 'a130')],
    });
    assert.deepEqual(lines, []);
  });
});
